80	/**
81	 * Pick the port forward that actually serves a game server's own port, not
82	 * just the first one on the record — a customer can add extra forwards
83	 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
84	 * mistaken for the game's real connect port. Falls back to the first forward
85	 * if none matches, so a server whose family isn't in GAME_PORT (or has no
86	 * exact-matching forward yet) still shows *something* rather than nothing.
87	 * Single shared helper so the provisioning-overlay connect string, the header
88	 * connect string, and the custom-domain DNS instructions can never drift from
89	 * each other the way three independent inline copies previously could.
90	 *
91	 * Keys on `joinPortFor`, NOT `GAME_PORT`. `GAME_PORT` is the health-CHECK map
92	 * and for eight families (rust, ark, projectzomboid, factorio, arkasa, soulmask,
93	 * squad, kf2) it deliberately names an RCON/query/admin port instead of the join
94	 * port — see its comment in lib/games.ts. Reading it here meant a Rust customer
95	 * was shown their RCON port, 28016, as the address to give their players. Found
96	 * live 2026-09-06 on a real fresh provision. The RCON forward still exists (the
97	 * provisioning health check runs through it), so this must select the join port
98	 * explicitly rather than rely on there being only one game forward.
99	 */
100	function gameForwardFor(server: {
101	  portForwards: { guestPort: number; publicPort: number }[];
102	  osTemplate: { family?: string | null };
103	  gamePlan?: { gameFamily?: string | null } | null;
104	}): { guestPort: number; publicPort: number } | undefined {
105	  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
106	  const joinPort = family && GAME_PORT[family] ? joinPortFor(family).port : undefined;
107	  const checkPort = family ? GAME_PORT[family]?.port : undefined;
108	  return (
109	    server.portForwards.find((f) => f.guestPort === joinPort) ??
110	    // The join forward can be legitimately absent on a server provisioned before
111	    // it was ever allocated — fall back to the check port rather than showing
112	    // nothing, same spirit as the final fallback below.
113	    server.portForwards.find((f) => f.guestPort === checkPort) ??
114	    server.portForwards[0]
115	  );
116	}
117	
118	function fmtUptime(seconds: number): string {
119	  if (!seconds || seconds <= 0) return "—";
120	  const d = Math.floor(seconds / 86400);
121	  const h = Math.floor((seconds % 86400) / 3600);
122	  const m = Math.floor((seconds % 3600) / 60);
123	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
124	}
125	
126	type LiveStats = {
127	  cpu?: number;
128	  mem?: number;
129	  maxmem?: number;
130	  uptime?: number;
131	  netin?: number;
132	  netout?: number;
133	} | null;
134	
135	export default async function ServerPage({
136	  params,
137	  searchParams,
138	}: {
139	  params: Promise<{ id: string }>;
140	  searchParams: Promise<{ tab?: string; purchase?: string }>;
141	}) {
142	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
143	  const user = await requireUser();
144	  const server = await db.server.findUnique({
145	    where: { id },
146	    include: {
147	      plan: true,
148	      osTemplate: true,
149	      project: true,
150	      portForwards: { orderBy: { publicPort: "asc" } },
151	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
152	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
153	      dedicatedIp: true,
154	      node: true,
155	      // Needed to price a renewal correctly: a game server bills its game plan's
156	      // flat price, not the base VPS plan's term price.
157	      gamePlan: true,
158	    },
159	  });
160	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
161	
162	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
163	  // display value through the decrypt fallback (legacy plaintext rows still work).
164	  const rootPassword = serverRootPassword(server);
165	
166	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct, ipMonthlyCentsLive] =
167	    await Promise.all([
168	      db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
169	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
170	      db.osTemplate.findMany({
171	        where: { active: true, category: "PLAIN_OS" },
172	        orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
173	      }),
174	      extraDiskPerGbCents(),
175	      backupPlusMonthlyCents(),
176	      // Live annual discount — feeds the "Renew now" quote below AND the resize
177	      // pickers, so an annual server's renewal/upgrade/downgrade all price against the
178	      // same rate it was sold at.
179	      annualDiscountPct(),
180	      // Fetched unconditionally now (not just `server.dedicatedIp ? … : 0`): the
181	      // "Add dedicated IP" card needs the live price to show a customer who does
182	      // NOT yet have one, same as extraDiskPriceCents above is fetched regardless
183	      // of whether this server currently holds any extra disk.
184	      dedicatedIpMonthlyCents(),
185	    ]);
186	
187	  // Retention offer: may this account still be shown "stay and save 50%" if it
188	  // attempts to cancel THIS server? Resolved once, server-side, and threaded
189	  // into CancelService rather than trusted client-side — see that function's
190	  // own doc comment (lib/actions-server-lifecycle.ts) for the full eligibility
191	  // rule. Skipped entirely for a free/already-deleting server, matching the
192	  // exact condition CancelService itself is only rendered under below.
193	  const cancellable = !server.isFree && server.status !== "DELETING";
194	  const retentionEligible = cancellable ? await checkRetentionOfferEligible(server.id) : false;
195	
196	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
197	  const owner =
198	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
199	  const renewTaxCtx = await taxContextForUser(owner);
200	
201	  // What "Renew now" will actually charge, priced through the SAME function the
202	  // action charges through, so the button cannot quote one figure and take
203	  // another. See lib/renewal-quote.ts for the incident.
204	  const renewQuote = renewalQuote(
205	    {
206	      termMonths: server.termMonths,
207	      extraDiskGB: server.extraDiskGB,
208	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
209	      // A game server is sold at its game plan's flat price, NOT the base VPS
210	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
211	      // a $4.99 product.
212	      gamePlan: server.gamePlan
213	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
214	        : null,
215	      dedicatedIp: server.dedicatedIp,
216	      wantsDedicatedIp: server.wantsDedicatedIp,
217	      backupTier: server.backupTier,
218	      grandfatheredRenewalCents: server.grandfatheredRenewalCents,
219	    },
220	    {
221	      ipMonthlyCents: server.dedicatedIp ? ipMonthlyCentsLive : 0,
222	      extraDiskPerGbCents: extraDiskPriceCents,
223	      backupPlusCents,
224	      annualDiscountPct: annualPct,
225	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
226	      // now quote are tax-inclusive, matching what renewNow charges.
227	      taxRatePercent: renewTaxCtx.ratePercent,
228	    },
229	  );
230	
231	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
232	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
233	  //
234	  // FIXED 2026-09-09: for a game server, "plan allowance" means the GAME
235	  // plan's disk, not the base VPS plan's — worker/index.ts's `provision()`
236	  // has used `server.gamePlan?.diskGB ?? server.plan.diskGB` since the
237	  // 2026-09-06 over-provisioning fix (a game plan is never LARGER than its
238	  // base VPS tier), but this page's own `totalDiskGB` was never updated to
239	  // match, so a game server's dashboard silently showed the bigger base-VPS
240	  // number here even though the VM itself was correctly provisioned at the
241	  // smaller, advertised size. Found live on a real Valheim server (30GB
242	  // advertised + actually provisioned, dashboard showed 50GB) — the exact
243	  // "advertised != displayed" trust problem the original fix existed to
244	  // prevent, just relocated to the display layer instead of provisioning.
245	  const baseDiskGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
246	  const totalDiskGB = effectiveDiskGB(baseDiskGB, server.extraDiskGB);
247	
248	  const publicIp = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
249	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
250	  const busy =
251	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
252	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
253	
254	  let live: LiveStats = null;
255	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
256	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
257	  let pveUnavailable = false;
258	
259	  if (server.vmid && steady && SANDBOX) {
260	    // Same "no real hypervisor to ask" case handled for the metrics chart
261	    // (app/api/metrics/route.ts) — a sandboxed vmid was never a real VM, so
262	    // vmStatus() below would just fail and leave every stat at its 0/—
263	    // default. Uptime is genuinely computed from the server's real
264	    // createdAt, not invented — everything else is a plausible, gently
265	    // varying idle-server reading capped to the server's real plan RAM.
266	    const ramMB = server.gamePlan?.ramMB ?? server.plan?.ramMB ?? 2048;
267	    const maxmem = ramMB * 1024 * 1024;
268	    live = {
269	      cpu: 0.14,
270	      mem: Math.round(maxmem * 0.48),
271	      maxmem,
272	      uptime: Math.max(0, Math.floor((Date.now() - server.createdAt.getTime()) / 1000)),
273	      netin: 184_320_000,
274	      netout: 92_160_000,
275	    };
276	  } else if (server.vmid && steady) {
277	    // Read through THIS server's own node's Proxmox client — vmids can
278	    // collide across nodes, so the bare vmStatus/listSnapshots/listBackups
279	    // (always the primary node) would show a customer someone else's VM's
280	    // stats the moment their server lives on a different node. Falls back to
281	    // the primary-node singleton only for the legacy case of a server with
282	    // no `node` relation at all (pre-multi-node rows).
283	    const conn = server.node ? pveForNode(server.node) : null;
284	    // listBackupsOn's own default storage id ("backup") is the PRIMARY's own
285	    // vzdump storage name — a non-primary node's is its own `storageHdd`
286	    // (worker/index.ts and lib/actions-server-ops.ts already resolve it this
287	    // way). Omitting this here made every node-2+ server's Backups tab fail
288	    // with "hypervisor is briefly unavailable" — confirmed live 2026-09-08,
289	    // Proxmox 500s on GET /nodes/<node>/storage/backup/content because that
290	    // storage id doesn't exist there (node-2's is "vmdata-hdd").
291	    const backupStorage = server.node
292	      ? server.node.isPrimary
293	        ? "backup"
294	        : (server.node.storageHdd ?? "backup")
295	      : "backup";
296	    const results = await Promise.allSettled([
297	      conn ? conn.vmStatus(server.vmid) : vmStatus(server.vmid),
298	      conn ? listSnapshotsOn(conn, server.vmid) : listSnapshots(server.vmid),
299	      conn ? listBackupsOn(conn, server.vmid, backupStorage) : listBackups(server.vmid),
300	    ]);
301	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
302	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
303	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
304	    pveUnavailable = results.some((r) => r.status === "rejected");
305	  }
306	
307	  // Dedicated-IP servers connect straight to their own public IP on port 22; NAT
308	  // servers use the platform public IP + the forwarded SSH port. (A dedicated
309	  // server has sshPort=null, which previously fell through to "provisioning…".)
310	  const sshCommand = server.dedicatedIp
311	    ? `ssh root@${server.dedicatedIp.address}`
312	    : server.sshPort
313	      ? `ssh root@${publicIp} -p ${server.sshPort}`
314	      : null;
315	
316	  // Single-item terminal list for this server — connect string computed the
317	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
318	
319	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
320	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
321	  const dedicated = !!server.dedicatedIp;
322	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
323	  const sftpPort = dedicated ? 22 : server.sshPort;
324	  /* A game server is one that was SOLD as a game server — `gamePlanId` — and
325	     its family is the game plan's, falling back to the OS template's.
326	     This used to test `osTemplate.family` alone, which is wrong whenever a game
327	     is installed on top of a plain OS image: `mc-survival` carries
328	     gamePlan.gameFamily="minecraft" on osTemplate.family="ubuntu", so it failed
329	     the test and rendered the VPS panel — no game console, no players, no mods,
330	     no game settings, for a Minecraft server. lib/game-config.ts's `familyFor`
331	     has always used this precedence; the page now matches it. */
332	  const isGameServer =
333	    server.gamePlanId !== null || GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
334	
335	  // Post-payment "setting up / it's live" interstitial. Connect string mirrors
336	  // the game-branch's own `connect` computation below via the shared
337	  // gameForwardFor() helper, so the two can never drift from each other.
338	  const overlayForward = isGameServer ? gameForwardFor(server) : undefined;
339	  const overlayConnect = isGameServer
340	    ? server.dedicatedIp
341	      ? `${server.dedicatedIp.address}${overlayForward ? `:${overlayForward.guestPort}` : ""}`
342	      : overlayForward
343	        ? `${publicIp}:${overlayForward.publicPort}`
344	        : publicIp || null
345	    : sshCommand;
346	  // Real (not cosmetic) step label when the worker has recorded one for this
347	  // server's CURRENT provisioning run — see lib/provisioning-step.ts. Null while
348	  // transitional but no checkpoint reached yet (or in SANDBOX, which completes
349	  // before any step is ever written) simply falls back to the overlay's existing
350	  // cosmetic cycling text.
351	  const liveStep = transitional ? await serverProvisioningStep(server.id) : null;
352	  /* The Nexion provisioning screen. It replaces <ProvisioningOverlay/> for the
353	     three states it covers — building, live, failed — and is driven by the SAME
354	     real signals the old one used: `server.status` and `serverProvisioningStep`.
355	     The design sandbox animated this on a timer; nothing here advances unless
356	     the worker actually reported a step.
357	
358	     This is the destination `payAndDeploy` redirects to, so it is the screen a
359	     customer really sees after ordering — the wizard's own step 5 is never
360	     reached on that path. */
361	  const overlay = transitional || purchase === "1" || server.status === "ERROR" ? (
362	    <Provisioning
363	      phase={server.status === "ERROR" ? "error" : transitional ? "working" : "ready"}
364	      liveStep={liveStep}
365	      /* Sandbox only: no hypervisor here means the worker never reports a step,
366	         so the stage list would sit inert forever and the screen could not be
367	         judged. Never true in production — NXEON_SANDBOX is not set there. */
368	      simulate={process.env.NXEON_SANDBOX === "1" && !liveStep}
369	      hostname={server.hostname}
370	      planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
371	      osName={server.osTemplate.name}
372	      connectAddress={overlayConnect}
373	      error={server.provisionError}
374	      dashboardHref={`/dashboard/servers/${server.id}`}
375	      service={isGameServer ? "game" : "vps"}
376	      /* Real figures off the plan the customer is actually being given — the
377	         same `totalDiskGB` the rest of the page uses, so the provisioning
378	         screen and the server page cannot quote different disk. */
379	      specs={[
380	        { icon: "cpu", text: `${server.plan.cpuCores} vCPU` },
381	        { icon: "ram", text: `${server.plan.ramMB / 1024} GB RAM` },
382	        { icon: "database", text: `${totalDiskGB} GB NVMe` },
383	      ]}
384	      slots={isGameServer ? server.gamePlan?.slots ?? null : null}
385	      /* `Node.region` is a slug ("sgp1"); REGION_LABELS is the one place that
386	         turns it into the name a customer recognises. */
387	      regionName={server.node ? REGION_LABELS[server.node.region] ?? null : null}
388	    />
389	  ) : null;
390	
391	  /* While the server is being built — or immediately after paying — this screen
392	     is the WHOLE page. The tabs, the access panel and the SSH box below are
393	     controls for a machine that does not exist yet: showing "provisioning…"
394	     inside a Root password field invites the customer to keep checking a box
395	     that cannot fill. They come back the moment the server is real, via the
396	     Continue button. */
397	  if (overlay) {
398	    return (
399	      <div className="min-h-[70vh]">
400	        {transitional && <AutoRefresh />}
401	        {overlay}
402	      </div>
403	    );
404	  }
405	
406	
407	  // Per-game customization (only for game servers with a customization schema).
408	  const gameFamily = familyFor(server);
409	  const gameSchema = schemaFor(gameFamily);
410	  const gameVariant =
411	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
412	      ? server.gameVariant
413	      : gameSchema?.defaultVariant ?? "";
414	  const gameValidated = gameFamily
415	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
416	    : null;
417	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
418	
419	  /* ---------- Tab: Overview ---------- */
420	  /* ---------- The panel's identity + vitals snapshot ----------
421	     Assembled once and handed to the shell. The address comes from
422	     lib/nx/connect-address.ts rather than being worked out again — this page
423	     had re-derived the same answer inline in four separate places. */
424	  const vpsUptime = await uptimeFor([server.id]);
425	
426	  // Memory comes from the worker-collected guest-agent sample (ServerMemSample),
427	  // not the live vmStatus() call above — Proxmox's own `mem`/`maxmem` balloon
428	  // fields are MemFree-based, not MemAvailable-based, so a VM with ordinary
429	  // disk/page-cache activity reads falsely high "memory used" even with plenty
