"use client";

import { useEffect, useState, type ReactNode } from "react";
import { GameHero } from "./GameHero";
import { GameOverviewPanel } from "./GameOverviewPanel";
import { GameConsole } from "../GameConsole";
import { ModsPanel } from "./ModsPanel";
import { GamePlayersHub } from "../GamePlayersHub";
import { GameWorlds } from "../GameWorlds";
import { GameCommandLibrary } from "../GameCommandLibrary";
import { GamePlayerHistory } from "../GamePlayerHistory";
import { GameSchedules } from "../GameSchedules";
import { GameBuildAI } from "../GameBuildAI";
import { Icon } from "@/components/nx/Icon";
import type { GameHeaderData } from "../types";
import type { ComponentProps } from "react";

type OverviewFacts = ComponentProps<typeof GameOverviewPanel>["facts"];

/**
 * The panel's shell: a pinned identity hero, a pinned tab rail, and one tab.
 *
 * NAVIGATION IS CONSOLIDATED from the thirteen tabs this replaced. Mods and
 * Plugins were two views of the same catalogue filtered by keyword, so they are
 * one tab with sub-tabs. The three Minecraft-only tabs are folded into the
 * section they belong to rather than appearing and disappearing from the rail
 * depending on which game you opened: Commands sits under Console (it is a
 * command reference for the console), History under Players, and Worlds under
 * Backups (they are save directories).
 *
 * The tab also lives in the URL properly now. The old shell wrote `?tab=` with
 * `history.replaceState`, which meant the browser back button skipped the whole
 * panel and a link to a tab could not be shared — and two worker notifications
 * deep-link into tabs, one of them to a `?tab=game settings` key that never
 * existed.
 */

type TabKey =
  | "overview" | "console" | "files" | "mods" | "backups"
  | "players" | "schedules" | "build" | "settings" | "activity";

const TABS: { key: TabKey; label: string; icon: string; badge?: string }[] = [
  { key: "overview",  label: "Overview",        icon: "donut" },
  { key: "console",   label: "Console",         icon: "terminal" },
  { key: "files",     label: "Files",           icon: "folder" },
  { key: "mods",      label: "Mods & Plugins",  icon: "cube" },
  { key: "backups",   label: "Backups",         icon: "archive" },
  { key: "players",   label: "Players",         icon: "users2" },
  { key: "schedules", label: "Schedules",       icon: "calendar" },
  /* Build with AI earns a tab rather than a card at the bottom of Overview,
     where it sat below three other panels and off the fold. It is a workflow —
     describe, Claude plans, you approve, we run it — not a widget. */
  { key: "build",     label: "Build with AI",   icon: "sparkles", badge: "AI" },
  { key: "settings",  label: "Settings",        icon: "gear" },
  { key: "activity",  label: "Activity",        icon: "activity" },
];

/** Old deep-links and worker notifications still point at the retired keys. */
const ALIASES: Record<string, TabKey> = {
  plugins: "mods",
  worlds: "backups",
  commands: "console",
  history: "players",
  manage: "settings",
  ai: "build",
  buildai: "build",
  "game settings": "settings",
  gamesettings: "settings",
  networking: "settings",
  resize: "settings",
};

function resolveTab(raw: string | undefined): TabKey {
  const k = (raw ?? "").toLowerCase().trim();
  if (TABS.some((t) => t.key === k)) return k as TabKey;
  return ALIASES[k] ?? "overview";
}


/* Players and Schedules still render through the shared `.card` class that the
   rest of the app uses. Rather than change that class globally — it is on every
   page — this restyles it only where those tabs mount, so the panel reads as one
   product while their internals stay untouched. */
const LEGACY_CARDS =
  "[&_.card]:rounded-[16px] [&_.card]:border-rim-hi " +
  "[&_.card]:bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))]";

export function GamePanelShell({
  serverId, gameFamily, header, facts, filesPanel, backupsPanel, settingsPanel, activityPanel, initialTab,
}: {
  serverId: string;
  gameFamily: string;
  header: GameHeaderData;
  facts: OverviewFacts;
  filesPanel: ReactNode;
  backupsPanel: ReactNode;
  settingsPanel: ReactNode;
  activityPanel: ReactNode;
  initialTab?: string;
}) {
  const isMc = gameFamily === "minecraft";
  /* Families with no remote console but a real log-tailing player poller
     (GameLogPlayers/logPlayerTrackingSweep — currently just Valheim). Session
     history works the same way it does for RCON families (real PlayerSession
     rows), so it earns the same sub-tabs as Minecraft rather than being hidden. */
  const isLogTracked = gameFamily === "valheim";
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
  const [modScope, setModScope] = useState<"mods" | "plugins">(
    () => ((initialTab ?? "").toLowerCase() === "plugins" ? "plugins" : "mods"),
  );
  const [consoleView, setConsoleView] = useState<"live" | "commands">(
    () => ((initialTab ?? "").toLowerCase() === "commands" ? "commands" : "live"),
  );
  const [playersView, setPlayersView] = useState<"live" | "history">(
    () => ((initialTab ?? "").toLowerCase() === "history" ? "history" : "live"),
  );

  /* Back/forward should move through tabs, not out of the panel. */
  useEffect(() => {
    const onPop = () => {
      const t = new URLSearchParams(window.location.search).get("tab") ?? undefined;
      setTab(resolveTab(t));
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const go = (t: TabKey) => {
    setTab(t);
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    window.history.pushState(null, "", url);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Hero and rail travel together, so identity, vitals and power controls
          are reachable from every tab without scrolling back up. */}
      <div className="sticky top-0 z-20 -mx-1 flex flex-col gap-2 bg-[color-mix(in_srgb,var(--color-bg)_82%,transparent)] px-1 pb-2 pt-1 backdrop-blur-xl">
        <GameHero serverId={serverId} gameFamily={gameFamily} data={header} />

        <nav className="flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-[rgba(6,14,36,.82)] p-1.5">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button
                key={t.key}
                type="button"
                onClick={() => go(t.key)}
                aria-current={on ? "page" : undefined}
                className={
                  "inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-semibold transition " +
                  (on
                    ? "bg-[linear-gradient(120deg,rgba(80,40,190,.55),rgba(30,44,130,.42))] text-white shadow-[inset_0_0_0_1px_rgba(139,92,255,.5)]"
                    : "text-tx-dim hover:bg-white/[0.05] hover:text-tx")
                }
              >
                <Icon name={t.icon} size={14} tone="inherit" className={on ? "text-[#fff]" : "text-tx-dim"} />
                {t.label}
                {t.badge && (
                  <span className="rounded-[5px] bg-[#7b3fef]/30 px-1.5 py-0.5 text-[9px] font-bold tracking-wide text-[#c4a6ff]">
                    {t.badge}
                  </span>
                )}
              </button>
            );
          })}
        </nav>
      </div>

      <div className="min-w-0">
        {tab === "overview" && (
          <GameOverviewPanel
            serverId={serverId}
            gameFamily={gameFamily}
            data={header}
            facts={facts}
            onNavigate={(t) => go(resolveTab(t))}
          />
        )}

        {tab === "console" && (
          <div className="flex flex-col gap-3">
            {isMc && (
              <SubTabs
                value={consoleView}
                onChange={setConsoleView}
                items={[{ key: "live", label: "Live console" }, { key: "commands", label: "Command reference" }]}
              />
            )}
            {consoleView === "live" || !isMc
              ? <GameConsole serverId={serverId} running={header.running} />
              : <div className={LEGACY_CARDS}><GameCommandLibrary serverId={serverId} running={header.running} /></div>}
          </div>
        )}

        {tab === "files" && filesPanel}

        {tab === "mods" && (
          <div className="flex flex-col gap-3">
            <SubTabs
              value={modScope}
              onChange={setModScope}
              items={[{ key: "mods", label: "Mods" }, { key: "plugins", label: "Plugins" }]}
            />
            <ModsPanel serverId={serverId} scope={modScope} />
          </div>
        )}

        {tab === "backups" && (
          <div className="flex flex-col gap-4">
            {backupsPanel}
            {isMc && <GameWorlds serverId={serverId} running={header.running} />}
          </div>
        )}

        {tab === "players" && (
          <div className="flex flex-col gap-3">
            {(isMc || isLogTracked) && (
              <SubTabs
                value={playersView}
                onChange={setPlayersView}
                items={[{ key: "live", label: "Online & access" }, { key: "history", label: "Session history" }]}
              />
            )}
            <div className={LEGACY_CARDS}>
              {playersView === "live" || !(isMc || isLogTracked)
                ? <GamePlayersHub serverId={serverId} running={header.running} playersMax={header.players.max} isMc={isMc} logTracked={isLogTracked} />
                : <GamePlayerHistory serverId={serverId} />}
            </div>
          </div>
        )}

        {tab === "schedules" && <div className={LEGACY_CARDS}><GameSchedules serverId={serverId} /></div>}

        {tab === "build" && (
          <div className={LEGACY_CARDS}>
            <GameBuildAI serverId={serverId} gameFamily={gameFamily} gameLabel={header.gameLabel} />
          </div>
        )}
        {tab === "settings" && settingsPanel}
        {tab === "activity" && activityPanel}
      </div>
    </div>
  );
}

function SubTabs<T extends string>({
  value, onChange, items,
}: {
  value: T; onChange: (v: T) => void; items: { key: T; label: string }[];
}) {
  return (
    <div className="flex w-fit gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
      {items.map((i) => (
        <button
          key={i.key}
          type="button"
          onClick={() => onChange(i.key)}
          aria-pressed={value === i.key}
          className={
            "rounded-[8px] px-3.5 py-1.5 text-[12.5px] font-semibold transition " +
            (value === i.key ? "bg-[#7b3fef]/25 text-tx" : "text-tx-dim hover:text-tx")
          }
        >
          {i.label}
        </button>
      ))}
    </div>
  );
}

