  SUSPENDED:    { dot: "bg-orange-400",  ring: "border-orange-400/40 bg-orange-950/60",   ink: "text-orange-300",  label: "Suspended" },
  PROVISIONING: { dot: "bg-sky-400 animate-pulse", ring: "border-sky-400/40 bg-sky-950/60", ink: "text-sky-300",   label: "Deploying" },
  PENDING:      { dot: "bg-sky-400 animate-pulse", ring: "border-sky-400/40 bg-sky-950/60", ink: "text-sky-300",   label: "Deploying" },
  REINSTALLING: { dot: "bg-sky-400 animate-pulse", ring: "border-sky-400/40 bg-sky-950/60", ink: "text-sky-300",   label: "Reinstalling" },
  ERROR:        { dot: "bg-red-400",     ring: "border-red-400/40 bg-red-950/60",         ink: "text-red-300",     label: "Error" },
};

/** A 24-point sparkline, or a flat baseline when there is no history yet. */
function Spark({ points, tone }: { points: number[]; tone: string }) {
  const W = 96, H = 26;
  const has = points.length >= 3;
  const src = has ? points : [0, 0];
  const max = Math.max(1, ...src);
  const step = W / Math.max(1, src.length - 1);
  const d = src.map((v, i) => `${i === 0 ? "M" : "L"}${(i * step).toFixed(1)},${(H - (v / max) * (H - 3) - 1.5).toFixed(1)}`).join(" ");
  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} className="overflow-visible" aria-hidden>
      <path d={d} fill="none" stroke={tone} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"
            opacity={has ? 1 : 0.28} />
    </svg>
  );
}

function Vital({
  label, value, sub, spark, tone, pct,
}: {
  label: string; value: string; sub?: string; spark?: number[]; tone?: string; pct?: number;
}) {
  return (
    <div className="flex min-w-[112px] flex-col gap-1">
      <span className="text-[9.5px] font-bold uppercase tracking-[0.16em] text-tx-faint">{label}</span>
      <span className="num text-[15px] font-bold leading-none text-white">{value}</span>
      {spark ? (
        <Spark points={spark} tone={tone ?? "#5fd0ff"} />
      ) : pct !== undefined ? (
        <span className="mt-1 h-[5px] w-full overflow-hidden rounded-full bg-white/10">
          <span className="block h-full rounded-full transition-[width] duration-500"
                style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: tone ?? "#5fd0ff" }} />
        </span>
      ) : null}
      {sub && <span className="text-[10.5px] text-tx-faint">{sub}</span>}
    </div>
  );
}

export function GameHero({
  serverId, gameFamily, data,
}: {
  serverId: string; gameFamily: string; data: GameHeaderData;
}) {
  const [players, setPlayers] = useState(data.players.online);
  const [cpu, setCpu] = useState<number[]>([]);
  const [mem, setMem] = useState<number[]>([]);
  const [copied, setCopied] = useState(false);
  const [moreOpen, setMoreOpen] = useState(false);
  const copyTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  /* Start/Restart/Stop anti-spam guard — see usePowerGuard. Locks on the click
     itself, follows the real GAME_POWER job (seconds to several minutes per
     game), then a short cooldown. */
  const power = usePowerGuard(data.power);
  const powerDisabled = power.locked || !data.canControl;

  /* While a real GAME_POWER job is in flight the pill says so. "Offline" for
     the three minutes a big Terraria world takes to load is what read as
     "nothing happened, click again". */
  const tone =
    power.stage && power.action
      ? { ...STATUS.PENDING, label: `${actionProgressive(power.action)}…` }
      : STATUS[data.status] ?? STATUS.STOPPED;
  const art = GAME_ART_SLUG[gameFamily as GameFamily];
  const display = GAME_DISPLAY[gameFamily as keyof typeof GAME_DISPLAY]?.name ?? data.gameLabel;
  const [logoOk, setLogoOk] = useState(true);
  const [heroOk, setHeroOk] = useState(true);

  const connect = data.customDomainVerified && data.customDomain ? data.customDomain : data.connect;
  const memPct = data.mem.usedBytes != null && data.mem.maxBytes ? (data.mem.usedBytes / data.mem.maxBytes) * 100 : 0;
  const diskPct = data.disk.maxGB ? (data.disk.usedGB / data.disk.maxGB) * 100 : 0;

  /* Live player count — RCON `list`. Only three families speak RCON, so this
     quietly stays at the server-rendered figure for the rest rather than
     showing an error on the hero. */
  useEffect(() => {
    if (!data.running) return;
    let alive = true;
    const poll = async () => {
      const r = await getGamePlayers(serverId).catch(() => null);
      if (alive && r?.ok) setPlayers(r.players.length);
    };
    void poll();
    const t = setInterval(poll, 15000);
    return () => { alive = false; clearInterval(t); };
  }, [serverId, data.running]);

  /* Real RRD history for the sparklines. No fallback shape: no history draws a
     flat line, which is what "we have not sampled this yet" looks like. */
  useEffect(() => {
    if (!data.running) return;
    let alive = true;
    const load = async () => {
      try {
        const res = await fetch(`/api/metrics?serverId=${serverId}&tf=hour`, { cache: "no-store" });
        if (!res.ok) return;
        const json: { data?: { cpu: number | null; mem: number | null; maxmem: number | null }[] } = await res.json();
        const rows = (json.data ?? []).slice(-24);
        if (!alive || rows.length < 3) return;
        setCpu(rows.map((r) => (r.cpu ?? 0) * 100));
        setMem(rows.map((r) => (r.mem && r.maxmem ? (r.mem / r.maxmem) * 100 : 0)));
      } catch { /* leave the baseline */ }
    };
    void load();
    const t = setInterval(load, 15000);
    return () => { alive = false; clearInterval(t); };
  }, [serverId, data.running]);

  const runPower = (action: "start" | "restart" | "stop") =>
    power.run(action, () => gamePower(serverId, action));
  /* The clicked button names what it is doing while it does it. */
  const spinning = (a: "start" | "restart" | "stop") => power.action === a && !!power.stage;
  const label = (a: "start" | "restart" | "stop", idle: string) => (spinning(a) ? `${actionProgressive(a)}…` : idle);

  const copy = () => {
    if (!connect) return;
    void navigator.clipboard?.writeText(connect);
    setCopied(true);
    if (copyTimer.current) clearTimeout(copyTimer.current);
    copyTimer.current = setTimeout(() => setCopied(false), 1600);
  };

  /* A dark island — this sits on the game's own dark key art, exactly like
     VpsHero does on the VPS render. Ink text on a screenshot is not a theme,
     it is a bug. */
  return (
    <header className="nx-dark-island relative min-h-[176px] overflow-hidden rounded-[18px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.72),rgba(2,7,20,.92))]">
      {/* ── the game's own key art ───────────────────────────────────────
          Full-bleed and CENTRED, faded symmetrically at both edges so it reads
          as part of the card rather than a picture pasted against one side. A
          vertical fade keeps the bottom edge clean, and a floor under it stops
          the vitals fighting the brightest part of a busy screenshot. */}
      {art && heroOk && (
        <span aria-hidden className="pointer-events-none absolute inset-0">
          <span
            className="block h-full w-full"
            style={{
              WebkitMaskImage: "linear-gradient(180deg, #000 0%, #000 58%, transparent 100%)",
              maskImage: "linear-gradient(180deg, #000 0%, #000 58%, transparent 100%)",
            }}
          >
            {/* eslint-disable-next-line @next/next/no-img-element -- local key art, outside the optimizer */}
            <img
              src={`/games/art/${art.hero}_hero.jpg`}
              alt=""
              /* Families whose real key-art hasn't been produced yet (see the
                 GAME_ART_SLUG "SCAFFOLD" comments in lib/games.ts) point at a
                 hero file that doesn't exist on disk. Unlike the poster/logo
                 images below, this one had no onError — a 404 rendered as a
                 broken-image glyph over the card instead of just falling back
                 to the header's own base gradient. Same onError-hides-it
                 convention already used for the logo image right below, and
                 for this same hero art in components/marketing/GameHero.tsx. */
              onError={() => setHeroOk(false)}
              className="h-full w-full object-cover object-center opacity-40"
              style={{
                WebkitMaskImage: "linear-gradient(90deg, transparent 0%, #000 20%, #000 80%, transparent 100%)",
                maskImage: "linear-gradient(90deg, transparent 0%, #000 20%, #000 80%, transparent 100%)",
              }}
            />
          </span>
          <span className="absolute inset-0"
                style={{ background: "linear-gradient(180deg,rgba(2,7,20,.3) 0%,rgba(2,7,20,.55) 55%,rgba(2,7,20,.86) 100%)" }} />
        </span>
      )}

      {/* The wordmark, centred over the art. 13 of 43 families have no logo
          drop-in; those show the game's name in type instead. */}
      {art && logoOk && (
        /* eslint-disable-next-line @next/next/no-img-element -- local brand art */
        <img
          src={`/games/art/${art.hero}_logo.png`}
          alt=""
          aria-hidden
          onError={() => setLogoOk(false)}
          className="pointer-events-none absolute left-1/2 top-5 hidden max-h-[76px] w-auto max-w-[260px] -translate-x-1/2 object-contain opacity-90 lg:block"
        />
      )}

      <div className="relative flex flex-col gap-3.5 px-5 py-4">
        {/* ── identity + power ─────────────────────────────────────────── */}
        <div className="flex flex-wrap items-center gap-x-5 gap-y-3">
          <span className="grid h-[58px] w-[58px] flex-none place-items-center overflow-hidden rounded-[14px] border border-rim-hi bg-[#050d20] shadow-lg">
            {art?.poster ? (
              /* eslint-disable-next-line @next/next/no-img-element -- local cover art */
              <img src={`/games/art/${art.poster}_poster.jpg`} alt="" className="h-full w-full object-cover" />
            ) : (
              <Icon name="gamepad" size={24} />
            )}
          </span>

          <div className="flex min-w-0 flex-col gap-1.5">
            <div className="flex flex-wrap items-center gap-2.5">
              <h1 className="truncate text-[26px] font-extrabold leading-none tracking-[-0.028em] text-white">{data.name}</h1>
              <span className={"inline-flex flex-none items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-bold backdrop-blur " + tone.ring + " " + tone.ink}>
                <span className={"h-[6px] w-[6px] rounded-full " + tone.dot} />
                {tone.label}
              </span>
            </div>
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[12.5px] text-tx-dim">
              <span className="font-semibold text-white/85">{display}</span>
              {connect && (
                <>
                  <span className="text-rim-hi">|</span>
                  <button type="button" onClick={copy} title={copied ? "Copied" : `Copy ${connect}`}
                          className="group/c inline-flex items-center gap-1.5 font-mono text-[12px] transition hover:text-white">
                    {connect}
                    <Icon name={copied ? "checkcircle" : "copy"} size={11} tone="inherit"
                          className={copied ? "text-emerald-400" : "opacity-50 transition-opacity group-hover/c:opacity-100"} />
                  </button>
                </>
              )}
              {data.location && (
                <>
                  <span className="text-rim-hi">|</span>
                  <span className="inline-flex items-center gap-1.5">
                    {data.locationCountry && <CountryFlag code={data.locationCountry} size={15} />}
                    {data.location}
                  </span>
                </>
              )}
            </div>
          </div>

          {/* Wraps on a phone — without flex-wrap/max-w-full the row ran past
              the hero's clipped edge and More was unreachable at 390px. */}
          <div className="ml-auto flex max-w-full flex-none flex-wrap items-center gap-2">
            {/* The in-progress button stays at full strength (it is the one
                telling you what is happening); the others fade as before. */}
            <button type="button" disabled={powerDisabled || data.running} aria-busy={spinning("start")} onClick={() => runPower("start")}
                    className={"inline-flex items-center gap-2 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.8)] px-3.5 py-2 text-[13px] font-semibold backdrop-blur transition hover:text-white disabled:cursor-not-allowed " + (spinning("start") ? "text-white" : "text-tx-dim disabled:opacity-40")}>
              <Icon name={spinning("start") ? "refresh2" : "bolt"} size={14} tone="inherit" className={spinning("start") ? "nx-spin" : undefined} /> {label("start", "Start")}
            </button>
            <button type="button" disabled={powerDisabled || !data.running} aria-busy={spinning("restart")} onClick={() => runPower("restart")}
                    className={"inline-flex items-center gap-2 rounded-[11px] border border-[#2a55b5] bg-[rgba(24,48,110,.8)] px-3.5 py-2 text-[13px] font-semibold text-white backdrop-blur transition hover:border-brand-400 disabled:cursor-not-allowed " + (spinning("restart") ? "" : "disabled:opacity-40")}>
              <Icon name={spinning("restart") ? "refresh2" : "refresh"} size={14} tone="inherit" className={spinning("restart") ? "nx-spin" : undefined} /> {label("restart", "Restart")}
            </button>
            <button type="button" disabled={powerDisabled || !data.running} aria-busy={spinning("stop")} onClick={() => runPower("stop")}
                    className={"inline-flex items-center gap-2 rounded-[11px] border border-red-500/45 bg-red-500/20 px-3.5 py-2 text-[13px] font-bold text-red-200 backdrop-blur transition hover:bg-red-500/30 disabled:cursor-not-allowed " + (spinning("stop") ? "" : "disabled:opacity-40")}>
              <Icon name={spinning("stop") ? "refresh2" : "xcircle"} size={14} tone="inherit" className={spinning("stop") ? "nx-spin" : undefined} /> {label("stop", "Stop")}
            </button>
            <span className="relative">
              <button type="button" onClick={() => setMoreOpen((v) => !v)} onBlur={() => setTimeout(() => setMoreOpen(false), 140)}
                      aria-label="More server actions"
                      className="inline-flex items-center gap-1.5 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.8)] px-3 py-2 text-[13px] font-semibold text-tx-dim backdrop-blur transition hover:text-white">
                More
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6" /></svg>
              </button>
              {moreOpen && (
                <span className="absolute right-0 top-[42px] z-30 flex w-[196px] flex-col overflow-hidden rounded-[11px] border border-rim-hi bg-surface py-1 shadow-2xl">
                  <Link href="/dashboard/services" className="px-3 py-2 text-[12.5px] text-tx-dim hover:bg-white/[0.05] hover:text-white">All my services</Link>
                  <Link href="/dashboard/billing" className="px-3 py-2 text-[12.5px] text-tx-dim hover:bg-white/[0.05] hover:text-white">Billing &amp; renewals</Link>
                  <Link href="/dashboard/support" className="px-3 py-2 text-[12.5px] text-tx-dim hover:bg-white/[0.05] hover:text-white">Get help with this</Link>
                </span>
              )}
            </span>
          </div>
        </div>

        {/* ── vitals, on their own band so they never sit on the artwork ── */}
        <div className="grid grid-cols-2 gap-x-8 gap-y-3 rounded-[13px] border border-rim-soft bg-[rgba(3,9,24,.72)] px-4 py-3 backdrop-blur-sm sm:grid-cols-4">
          <Vital
            label="Players"
            value={data.players.max ? `${players} / ${data.players.max}` : String(players)}
            pct={data.players.max ? (players / data.players.max) * 100 : 0}
            tone="linear-gradient(90deg,#34d399,#5fd0ff)"
          />
          <Vital label="CPU" value={`${Math.round(data.cpuPct)}%`} spark={cpu} tone="#5fd0ff" />
          <Vital
            label="RAM"
            value={
              data.mem.usedBytes != null
                ? `${fmtBytes(data.mem.usedBytes)} / ${fmtBytes(data.mem.maxBytes)}`
                : `— / ${fmtBytes(data.mem.maxBytes)}`
            }
            pct={memPct}
            tone="linear-gradient(90deg,#7b3fef,#c33bea)"
          />
          <Vital
            label="Disk"
            value={`${data.disk.usedGB} / ${data.disk.maxGB} GB`}
            pct={diskPct}
            tone={diskPct > 90 ? "linear-gradient(90deg,#f87171,#fb923c)" : "linear-gradient(90deg,#f59e0b,#fbbf24)"}
          />
        </div>
      </div>

      {/* What the power controls are doing, how the last action ended, or
          what else is holding them — never a silently greyed-out button. */}
      <PowerStatusNote guard={power} kind="game" layout="strip" />
    </header>
  );
}
