/**
 * Settings, reorganised.
 *
 * What this replaces was one column of eleven unrelated cards: the server's
 * name, then its tier, then a dedicated-IP purchase, then the game's own
 * config, then auto-update, then a SECOND copy of the Schedules tab, then the
 * network block, then SSH credentials — with Access, the thing a customer
 * hunts for most often, at the very bottom.
 *
 * Now each of those belongs to a named section reachable from a rail, in the
 * order of how often they are wanted, with the destructive ones fenced off at
 * the end in red. The sections are slots: the page composes what goes in them,
 * so nothing that worked before is lost.
 */

export type SettingsSectionKey =
  | "upgrade" | "billing" | "server" | "game" | "network" | "access" | "danger";

export type SettingsSlots = Partial<Record<SettingsSectionKey, ReactNode>>;

const SECTIONS: { key: SettingsSectionKey; label: string; sub: string; icon: string; tone?: "danger" }[] = [
  { key: "upgrade", label: "Resources",    sub: "Plan, slots and storage",   icon: "bolt" },
  { key: "billing", label: "Billing",      sub: "Renewal and auto-renew",    icon: "card" },
  { key: "server",  label: "Server",       sub: "Name, updates, behaviour",  icon: "gear" },
  { key: "game",    label: "Game settings",sub: "This game's own options",   icon: "gamepad" },
  { key: "network", label: "Network",      sub: "Connect address and domain",icon: "globe" },
  { key: "access",  label: "Server access",sub: "SSH, SFTP and credentials", icon: "key" },
  { key: "danger",  label: "Danger Zone",  sub: "Reinstall, wipe or cancel", icon: "warntriangle", tone: "danger" },
];

export function GameSettingsShell({ slots, gameLabel }: { slots: SettingsSlots; gameLabel: string }) {
  const shown = SECTIONS.filter((s) => slots[s.key]);
  const [sec, setSec] = useState<SettingsSectionKey>(shown[0]?.key ?? "server");
  const active = shown.find((s) => s.key === sec) ?? shown[0];

  if (!active) return null;

  return (
    <div className="grid gap-4 lg:grid-cols-[252px_minmax(0,1fr)]">
      <nav className="flex h-fit flex-col gap-1 rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-2">
        {shown.map((s) => {
          const on = sec === s.key;
          const danger = s.tone === "danger";
          return (
            <button
              key={s.key}
              type="button"
              onClick={() => setSec(s.key)}
              aria-current={on ? "true" : undefined}
              className={
                "flex items-center gap-3 rounded-[11px] border px-3 py-2.5 text-left transition " +
                (on
                  ? danger
                    ? "border-red-500/45 bg-red-500/12"
                    : "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))]"
                  : "border-transparent hover:bg-white/[0.04]")
              }
            >
              <Icon
                name={s.icon}
                size={16}
                tone="inherit"
                className={"flex-none " + (danger ? "text-red-400" : on ? "text-white" : "text-tx-dim")}
              />
              <span className="flex min-w-0 flex-col">
                <span className={"truncate text-[13px] font-bold " + (danger ? "text-red-300" : on ? "text-white" : "text-tx-dim")}>
                  {s.key === "game" ? `${gameLabel} settings` : s.label}
                </span>
                <span className="truncate text-[11px] text-tx-faint">{s.sub}</span>
              </span>
            </button>
          );
        })}
      </nav>

      {/* The slotted sections keep their own cards; this only groups them. */}
      <div className="flex min-w-0 flex-col gap-4 [&_.card]:rounded-[16px]">
        {slots[active.key]}
      </div>
    </div>
  );
}

