      listHostingAppMenu().catch(() => []),
      listFtpUsers(account.id).catch(() => []),
      hostingStorageBreakdown(account.id).catch(() => null),
      listHostingActivity(account.id, 24).catch(() => []),
      db.hostingPlan.count({
        where: { active: true, priceCents: { gt: account.planPriceCents } },
      }).catch(() => 0),
    ]);

  // The `siteKey` association lives on the row but isn't on HostingDbView — read
  // it alongside so the per-website Database section can name its database.
  const dbSiteKeys = await db.hostingDatabase
    .findMany({ where: { accountId: account.id }, select: { id: true, siteKey: true } })
    .catch(() => [] as { id: string; siteKey: string | null }[]);
  const siteKeyById = new Map(dbSiteKeys.map((d) => [d.id, d.siteKey]));

  // Real mailbox count for the plan's domain — only meaningful once the bundled
  // subscription exists. No subscription means there is nothing to count, which
  // is not the same as a count of zero, so it stays null and the tile says why.
  const emailSub = await db.emailSubscription
    .findFirst({
      where: { domainName: account.primaryDomain, status: { not: "CANCELLED" } },
      select: { id: true, _count: { select: { mailboxes: true } } },
    })
    .catch(() => null);

  const thumbByKey = new Map(thumbs.map((t) => [t.siteKey, t]));
  const siteCards: HostingSiteCard[] = sites.map((s) => ({ ...s, thumb: thumbByKey.get(s.key) ?? null }));

  const lastBackup = backups[0] ?? null;
  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;

  const data: HostingPanelData = {
    account,
    sites: siteCards,
    sftpHost: raw?.node?.sshHost || raw?.node?.hostnameFqdn || raw?.node?.publicIp || null,
    sftpPort: raw?.node?.sshPort ?? 22,
    hasSftpPassword: !!raw?.sftpPasswordEnc,
    mailboxesUsed: emailSub ? emailSub._count.mailboxes : null,
    emailReady: !!emailSub,
    mailboxesIncluded: raw?.plan?.mailboxes ?? account.planMailboxes,
    bandwidthTB: raw?.plan?.bandwidthTB ?? 0,
    databases: dbs.map((d) => ({ ...d, siteKey: siteKeyById.get(d.id) ?? null })),
    databasesUsed: dbs.length,
    appMenu,
    ftpUsers,
    backupCount: backups.length,
    lastBackupAt: lastBackup?.createdAt ?? null,
    lastBackupBytes: lastBackup?.sizeBytes ?? null,
    storage: storage && !("error" in storage) ? storage : null,
    activity,
    // The charge the renewal sweep actually takes, on the term this account was
    // SOLD on — never plan.priceCents, which is the monthly rate.
    renewalCents: termPriceCents(account.planPriceCents, account.termMonths, account.annualDiscountPct ?? undefined),
    renewalTerm: termLabel(account.termMonths),
    extraDiskGB: account.extraDiskGB,
    canUpgrade: upgradePlanCount > 0,
  };

  const sftpAddress = data.sftpHost ? `sftp://${account.username}@${data.sftpHost}` : null;

  /* The provisioning screen, gated the SAME way the VPS page gates it: while the
     account is genuinely being built, immediately after an order (`?purchase=1`),
     or on a failure. The old hosting page rendered it UNCONDITIONALLY, so every
     visit to a healthy months-old account opened with a full-width "Your hosting
     is ready ✓ · Open the panel" celebration above the dashboard the customer was
     already looking at — one of the contradictory states this redesign removes.

     An install still running on an otherwise-live account no longer takes the
     screen either: that belongs in Activity, which is where it now appears. */
  const showOverlay =
    transitional || purchase === "1" || account.status === "ERROR" || account.status === "FAILED";

  return (
    <div>
      {showOverlay && (
        <Provisioning
          phase={account.status === "ERROR" || account.status === "FAILED" ? "error" : transitional ? "working" : "ready"}
          liveStep={stepLabel}
          simulate={process.env.NXEON_SANDBOX === "1" && !stepLabel}
          service="hosting"
          hostname={account.primaryDomain}
          planName={account.planName}
          osName=""
          connectAddress={sftpAddress}
          error={account.error}
          dashboardHref={`/dashboard/hosting/${account.id}`}
          specs={[
            { icon: "database", text: `${Math.round(account.diskQuotaMB / 1024)} GB storage` },
            { icon: "globe3", text: `${account.maxSites + 1} website${account.maxSites === 0 ? "" : "s"}` },
            {
              icon: "envelope",
              text: data.mailboxesIncluded < 0 ? "Unlimited mailboxes" : `${data.mailboxesIncluded} mailboxes`,
            },
          ]}
        />
      )}
      {(transitional || installStepActive) && <AutoRefresh />}

      <HostingPanelShell
        data={data}
        initialTab={tab}
        initialSite={site}
        initialPath={path}
        initialSection={section}
      />
    </div>
  );
}
