export type SubSection<K extends string> = {
  key: K;
  label: string;
  sub: string;
  icon: string;
  tone?: "danger";
};

export function SubNav<K extends string>({ sections, slots, initial }: {
  sections: SubSection<K>[];
  slots: Partial<Record<K, ReactNode>>;
  initial?: K;
}) {
  const shown = sections.filter((s) => slots[s.key]);
  const [sec, setSec] = useState<K | undefined>(initial ?? shown[0]?.key);
  const active = shown.find((s) => s.key === sec) ?? shown[0];

  if (!active) return null;

  return (
    <div className="grid gap-4 lg:grid-cols-[252px_minmax(0,1fr)]">
      <nav className="flex h-fit flex-col gap-1 rounded-[16px] border border-rim-hi bg-surface p-2">
        {shown.map((s) => {
          const on = active.key === s.key;
          const danger = s.tone === "danger";
          return (
            <button
              key={s.key}
              type="button"
              onClick={() => setSec(s.key)}
              aria-current={on ? "true" : undefined}
              className={
                "flex items-center gap-3 rounded-[11px] border px-3 py-2.5 text-left transition " +
                (on
                  ? danger
                    ? "border-red-500/45 bg-red-500/12"
                    : "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))]"
                  : "border-transparent hover:bg-[color-mix(in_srgb,var(--fg)_4%,transparent)]")
              }
            >
              <Icon
                name={s.icon}
                size={16}
                tone="inherit"
                className={"flex-none " + (danger ? "text-red-400" : on ? "text-[#fff]" : "text-tx-dim")}
              />
              <span className="flex min-w-0 flex-col">
                <span className={"truncate text-[13px] font-bold " + (danger ? "text-red-300" : on ? "text-[#fff]" : "text-tx-dim")}>
                  {s.label}
                </span>
                <span className="truncate text-[11px] text-tx-faint">{s.sub}</span>
              </span>
            </button>
          );
        })}
      </nav>

      <div className="flex min-w-0 flex-col gap-4 [&_.card]:rounded-[16px]">{slots[active.key]}</div>
    </div>
  );
}
    url.searchParams.set("tab", t);
    if (opts.site) url.searchParams.set("site", opts.site);
    else if (opts.site === null) url.searchParams.delete("site");
    window.history.pushState(null, "", url);
