                {t.label}
              </button>
            );
          })}
        </nav>
      </div>

      <div className="min-w-0">
        {tab === "overview" && (
          <HostingOverviewPanel
            data={data}
            onOpenSite={(key) => go("websites", { site: key })}
            onGo={(t, s) => go(t as TabKey, { section: s })}
            onRefresh={refresh}
          />
        )}

        {tab === "websites" && (
          <HostingWebsitesPanel
            data={data}
            selected={site}
            onSelect={(key) => go("websites", { site: key })}
            onRefresh={refresh}
          />
        )}

        {tab === "files" && (
          active
            ? <HostingFilesPanel data={data} initialPath={initialPath} />
            : <NotReady what="The file manager" />
        )}

        {tab === "databases" && (
          active
            ? <HostingDatabasesPanel data={data} onRefresh={refresh} />
            : <NotReady what="Databases" />
        )}

        {tab === "email" && <HostingEmailPanel data={data} />}

        {tab === "apps" && (
          active ? <HostingAppsPanel data={data} onRefresh={refresh} /> : <NotReady what="One-click apps" />
        )}

        {tab === "cron" && (
          active ? <HostingCronPanel data={data} /> : <NotReady what="Scheduled tasks" />
        )}

        {tab === "backups" && (
          active ? <HostingBackupsPanel data={data} onRefresh={refresh} /> : <NotReady what="Backups" />
        )}

        {tab === "activity" && <HostingActivityPanel data={data} onRefresh={refresh} />}

        {tab === "settings" && (
          <HostingSettingsShell data={data} initial={section} onRefresh={refresh} />
        )}
      </div>
    </div>
  );
}

/** One wording for every tab that needs a live account, so a customer mid-setup
 *  gets the same answer everywhere instead of four different empty states. */
function NotReady({ what }: { what: string }) {
  return (
    <div className="card card-glass flex flex-col items-center px-6 py-14 text-center">
      <span className="grid h-[44px] w-[44px] place-items-center rounded-[13px] border border-rim-hi bg-well">
        <Icon name="refresh2" size={19} className="nx-spin" />
      </span>
      <p className="mt-3.5 text-[14.5px] font-extrabold text-tx">{what} isn’t ready yet</p>

      : STATUS[data.status] ?? STATUS.STOPPED;

  return (
    /* A dark island. The hero sits on the product's own dark server render, so
        its copy has to stay light in both themes — flipping it to ink would put
        dark text on a dark photograph. Same mechanism the rail and top bar use:
        it re-declares the dark tokens for its own subtree. */
    <header className="nx-dark-island card card-glass relative overflow-hidden p-0" style={{ "--tone": "#7b3fef" } as React.CSSProperties}>
      {/* backdrop */}
      <span aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <span
          className="block h-full w-full"
          style={{
            WebkitMaskImage: "linear-gradient(180deg, #000 0%, #000 58%, transparent 100%)",
            maskImage: "linear-gradient(180deg, #000 0%, #000 58%, transparent 100%)",
          }}
        >
          {/* eslint-disable-next-line @next/next/no-img-element -- local art, outside the optimizer */}
          <img
            src="/nx/preview/vps.webp"
            alt=""
            className="h-full w-full object-cover object-center opacity-[0.42]"
            style={{
              WebkitMaskImage: "linear-gradient(90deg, transparent 0%, #000 26%, #000 80%, transparent 100%)",
              maskImage: "linear-gradient(90deg, transparent 0%, #000 26%, #000 80%, transparent 100%)",
            }}
          />
        </span>
        {/* A darker column under the copy so the art never costs readability. */}
        <span
          className="absolute inset-0"
          style={{
            background:
              "linear-gradient(90deg, rgba(6,13,34,.96) 0%, rgba(6,13,34,.86) 34%, rgba(6,13,34,.42) 62%, rgba(6,13,34,.72) 100%)",
          }}
        />
      </span>

      <div className="relative z-[1] flex flex-wrap items-start justify-between gap-x-6 gap-y-4 px-5 py-4">
        {/* ── left: identity ──────────────────────────────────────────── */}
        <div className="flex min-w-0 flex-1 items-start gap-4">
          <span className="grid h-[62px] w-[62px] flex-none place-items-center overflow-hidden rounded-[16px] border border-rim-hi bg-well shadow-[0_0_28px_-10px_rgba(111,71,245,.8)]">
            {/* eslint-disable-next-line @next/next/no-img-element -- local product mark */}
            <img src="/nx/svc/vps.webp" alt="" className="h-full w-full object-cover" />
          </span>

          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2.5">
              <h1 className="truncate text-[25px] font-extrabold leading-[1.05] tracking-[-0.03em] text-tx sm:text-[29px]">
                {data.name}
              </h1>
              <StatusPill tone={st.tone} label={st.label} live={st.live} />
            </div>

            {/* IP, OS and region — the three things you check before anything. */}
            <div className="mt-2.5 flex flex-wrap items-center gap-x-4 gap-y-2">
              {data.connect.address && <CopyChip label="IP" value={data.connect.address} />}

              {/* The distribution's real mark, via AppLogo — the same component
                  and the same /public/logos set the rest of the portal uses.
                  A tinted generic cloud glyph was standing in for it. */}
              <span className="flex items-center gap-2">
                <AppLogo family={data.osFamily} name={data.osName} size={18} />
                <span className="text-[12.5px] font-semibold text-tx-body">{data.osName}</span>
              </span>

              {data.location.label && (
                <span className="flex items-center gap-2">
                  {data.location.country && <CountryFlag code={data.location.country} size={14} />}
                  <span className="text-[12.5px] font-semibold text-tx-body">{data.location.label}</span>
                </span>
              )}
            </div>

            {/* specs */}
            <div className="mt-3 flex flex-wrap items-center gap-x-6 gap-y-2">
              <Spec icon="cpu" value={`${data.specs.vcpu} vCPU`} label="Processor" />
              <Spec icon="ram" value={`${Math.round(data.specs.ramMB / 1024)} GB`} label="Memory" />
              <Spec icon="database" value={`${data.specs.diskGB} GB`} label="NVMe SSD" />
              <Spec icon="transfer" value={`${data.bandwidth.allowanceTB} TB`} label="Bandwidth" />
            </div>
          </div>
        </div>

        {/* ── right: actions ──────────────────────────────────────────── */}
        <VpsPowerControls
          serverId={data.serverId}
          serverName={data.name}
          status={data.status}
          busy={busy}
          power={power}
          terminalSlot={
            data.status === "RUNNING" ? (
              <OpenTerminalButton servers={[{ id: data.serverId, hostname: data.hostname }]} />
            ) : null
          }
        />
      </div>
    </header>
  );
}

export function VpsStateBanner({ data, suspendReason, provisionError }: {
  data: VpsHeaderData;
  suspendReason: string | null;
  provisionError: string | null;
}) {
  if (data.status === "SUSPENDED") {
    return (
      <div className="card card-glass flex flex-wrap items-center gap-3 border-orange-500/40 bg-orange-950/30 px-4 py-3 text-[13px] text-orange-200">
        <Icon name="warntriangle" size={16} tone="inherit" />
        <span className="min-w-0 flex-1">
          <span className="font-bold">This server is suspended.</span>{" "}
          {suspendReason || "Contact support if you believe this is a mistake."}
        </span>
        <Link href="/dashboard/support" className="font-semibold underline underline-offset-2">Open a ticket</Link>
      </div>
    );
  }
  if (data.status === "ERROR") {
    return (
      <div className="card card-glass flex items-center gap-3 border-red-500/40 bg-red-950/30 px-4 py-3 text-[13px] text-red-200">
        <Icon name="warntriangle" size={16} tone="inherit" />
        <span><span className="font-bold">Provisioning failed.</span> {provisionError || "Our team has been notified."}</span>
      </div>
    );
  }
  if (data.transitional) {
    return (
      <div className="card card-glass flex items-center gap-3 border-sky-500/35 bg-sky-950/25 px-4 py-3 text-[13px] text-sky-200">
        <Icon name="refresh2" size={15} tone="inherit" className="nx-spin" />
        {data.status === "DELETING"
          ? "This server is being deleted."
          : "Being set up — usually under two minutes. This page refreshes itself."}
      </div>
    );
  }
  return null;
}

