"use server";

/**
 * Server actions for first-run tours: the ONLY writer of UserTourProgress.
 *
 *  - Signed-in customer required (requireUser).
 *  - NEVER writes while an admin is impersonating: an admin walking through a
 *    customer's panel must not mark the customer's tour as seen. The call is a
 *    silent no-op ({ ok: true, persisted: false }) so the engine still runs.
 *  - serviceKey is allow-listed (lib/tours/trigger.ts isValidServiceKey) and
 *    step indexes are clamped, so a client can't fill the table with junk.
 *  - Throttled per account — the engine writes on start, on each step (for
 *    resume) and on finish/skip, which is at most a few dozen writes per run.
 */

import { requireUser, impersonating } from "@/lib/auth";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import {
  applyTourEvent,
  isValidServiceKey,
  TOUR_OPT_OUT_KEY,
  type ProgressRow,
  type TourEvent,
} from "./trigger";
import type { TourStatus } from "./types";

export type TourWriteResult = { ok: true; persisted: boolean } | { ok: false; error: string };

function parseEvent(raw: unknown): TourEvent | null {
  if (!raw || typeof raw !== "object") return null;
  const e = raw as { type?: unknown; step?: unknown };
  const step = typeof e.step === "number" ? e.step : undefined;
  switch (e.type) {
    case "start":
      return { type: "start" };
    case "step":
      return step === undefined ? null : { type: "step", step };
    case "complete":
      return { type: "complete", step };
    case "dismiss":
      return { type: "dismiss", step };
    default:
      return null;
  }
}

async function writeEvent(userId: string, serviceKey: string, ev: TourEvent): Promise<void> {
  const existing = await db.userTourProgress.findUnique({
    where: { userId_serviceKey: { userId, serviceKey } },
    select: { status: true, lastStep: true, completedAt: true, dismissedAt: true },
  });
  const prev: ProgressRow | null = existing
    ? { ...existing, status: existing.status as TourStatus }
    : null;
  const next = applyTourEvent(prev, ev);
  await db.userTourProgress.upsert({
    where: { userId_serviceKey: { userId, serviceKey } },
    create: { userId, serviceKey, ...next },
    update: next,
  });
}

/** Record one tour event (start / step / complete / dismiss) for the signed-in customer. */
export async function recordTourEvent(serviceKey: string, event: unknown): Promise<TourWriteResult> {
  const user = await requireUser();
  if (!isValidServiceKey(serviceKey) || serviceKey === TOUR_OPT_OUT_KEY) {
    return { ok: false, error: "Unknown tour." };
  }
  const ev = parseEvent(event);
  if (!ev) return { ok: false, error: "Unknown tour event." };
  if (await impersonating()) return { ok: true, persisted: false };
  const rl = checkRateLimit(`tour:${user.id}`, { max: 240, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) return { ok: false, error: "Too many requests." };
  await writeEvent(user.id, serviceKey, ev);
  return { ok: true, persisted: true };
}

/**
 * "Don't show tours again": ends the current tour (dismissed) AND records the
 * global opt-out, so no future service auto-starts one. Replays from the
 * "Take the tour" button still work.
 */
export async function optOutOfTours(currentServiceKey: string, step?: number): Promise<TourWriteResult> {
  const user = await requireUser();
  if (await impersonating()) return { ok: true, persisted: false };
  const rl = checkRateLimit(`tour:${user.id}`, { max: 240, windowMs: 10 * 60 * 1000 });
  if (!rl.ok) return { ok: false, error: "Too many requests." };
  if (isValidServiceKey(currentServiceKey) && currentServiceKey !== TOUR_OPT_OUT_KEY) {
    await writeEvent(user.id, currentServiceKey, { type: "dismiss", step });
  }
  await writeEvent(user.id, TOUR_OPT_OUT_KEY, { type: "dismiss" });
  return { ok: true, persisted: true };
}

