/**
 * Game-server tours — one per family that has genuinely distinct features, and
 * a solid generic tour (still capability-aware) for every other family.
 *
 * Every claim here is checked against the real panel:
 *   - tabs + sub-tabs:   components/customer/gamepanel/v2/GamePanelShell.tsx
 *   - settings sections: components/customer/gamepanel/v2/GameSettingsShell.tsx
 *   - game settings form + "restart" tags + server type: components/customer/GameSettings.tsx
 *   - which families can push settings live: lib/game-config.ts REAL_APPLY_FAMILIES
 *   - which have a remote console / player list: lib/game-control.ts (rcon: "source")
 *   - which have one-click mod installs: lib/mod-install-support.ts INSTALLABLE_FAMILIES
 *   - subdomains: page.tsx network section (minecraft, bedrock, HOSTNAME_CONNECT_FAMILIES)
 * If one of those changes, the context flags below change with it — the copy
 * is chosen from the flags, never hard-coded per family where a flag exists.
 *
 * Pure data + string building. No Prisma, no React.
 */

import type { TourDef, TourStep } from "./types";

export type GameTourContext = {
  family: string;
  /** Display name, e.g. "Minecraft", "ARK: Survival Evolved". */
  gameName: string;
  /** Settings → "<Game> settings" section exists (game plan + schema). */
  hasGameSettings: boolean;
  /** The worker can write those settings into the running server. */
  canApply: boolean;
  /** Server-type / loader choices offered by the settings form, by label. */
  variants: string[];
  /** The schema has a version picker (Minecraft Java/Bedrock). */
  hasVersion: boolean;
  /** Remote console (Source RCON) — console commands + live player list/kick/ban. */
  rcon: boolean;
  /** No console, but a real log-tailing player list (Valheim). */
  logTracked: boolean;
  /** One-click installs from the Mods & Plugins tab actually work for this family. */
  modsInstallable: boolean;
  /** Settings → Network offers a subdomain. */
  subdomain: boolean;
  /** Free server (no billing/renewal). */
  isFree: boolean;
};

/* ── per-family facts the flags can't express ─────────────────────────── */

type FamilyCopy = {
  /** How a player joins, in the game's own words. */
  connect: string;
  /** Mods tab body when the family has one-click installs. */
  mods?: string;
  /** Extra settings bullets worth calling out for this game. */
  settings?: string[];
  /** Console body override. */
  console?: string;
  /** Players body override. */
  players?: string;
};

const FAMILY: Record<string, FamilyCopy> = {
  minecraft: {
    connect:
      "In Minecraft (Java Edition) open Multiplayer → Add Server and paste this address. Click it here to copy it.",
    mods:
      "Plugins (Paper/Purpur) and mods (Fabric/Forge) install in one click from our catalogue. Pick the sub-tab that matches your server type, install, then restart so it loads.",
    settings: [
      "Server type: Vanilla, Paper/Purpur for plugins, Fabric/Forge for mods.",
      "Minecraft version: match what your mods or plugins target.",
      "Fields tagged RESTART apply after the next restart.",
    ],
    console:
      "The live server log, plus a command line. Type commands without the slash — e.g. op YourName or say Hello. The Command reference sub-tab lists the useful ones.",
    players:
      "See who's online, kick or ban, and manage the Whitelist and Operators. Turn the whitelist on in Settings first. Inventory and Roles & Permissions live here too.",
  },
  bedrock: {
    connect:
      "In Minecraft Bedrock open Play → Servers → Add Server, then enter the address and the port as separate fields.",
    settings: [
      "Bedrock version: stay on Latest so phones and consoles can join.",
      "Whitelist, game mode and difficulty live here.",
      "Fields tagged RESTART apply after the next restart.",
    ],
  },
  valheim: {
    connect:
      "In Valheim choose Join Game → Add server and enter this address. Players will need the server password you set.",
    mods:
      "Switch the server type to BepInEx in Settings first — mods from the catalogue only load on a BepInEx server. Install, then restart.",
    settings: [
      "Server password: Valheim requires at least 5 characters.",
      "World modifiers: death penalty, portals, raids.",
      "Admin and whitelisted SteamIDs.",
    ],
    players:
      "Valheim has no remote console, so the player list is read from the server log as people join and leave. Session history shows who played and when.",
  },
  terraria: {
    connect:
      "In Terraria choose Multiplayer → Join via IP, enter the address, then the port, then the server password if you set one.",
    mods:
      "Your server runs TShock, so this tab installs TShock plugins. Each plugin is tested to load on restart, and is rolled back if it doesn't.",
    settings: [
      "World size, name, seed and difficulty — these shape a NEW world.",
      "Server password and max players.",
    ],
  },
  rust: {
    connect:
      "In Rust press F1 to open the console and type client.connect followed by this address.",
    mods:
      "Set the server type to Oxide/uMod or Carbon in Settings, then install plugins here and restart.",
    settings: [
      "Server type: Vanilla, Oxide/uMod or Carbon (for plugins).",
      "World size and seed — changing them generates a new map.",
    ],
    console:
      "The live server log. Rust's web-based remote console isn't connected yet, so commands are run in-game by an admin; power, logs, schedules and backups all work.",
  },
  ark: {
    connect:
      "In ARK search for your server name in the server browser, or open the console and type open followed by this address.",
    mods:
      "ARK mods come from the Steam Workshop: installing one here adds its Workshop ID, and the server downloads it itself on the next restart.",
    settings: [
      "Map: The Island, The Center, Ragnarok, Scorched Earth or Aberration.",
      "XP, taming and harvest rates, plus PvE mode.",
      "Admin password — keep it private.",
    ],
  },
  arkasa: {
    connect: "In ARK: Survival Ascended, find your server in the server browser by name, or join with this address.",
  },
  cs2: {
    connect:
      "In Counter-Strike 2 open the developer console (~) and type connect followed by this address.",
    settings: [
      "Game mode: Competitive, Wingman, Casual or Deathmatch.",
      "Game Server Login Token — needed for your server to be listed and joinable from the internet.",
      "Server and RCON passwords.",
    ],
    console:
      "The live log plus a remote console. Type server commands here — e.g. changelevel de_dust2 or mp_restartgame 1.",
  },
  palworld: {
    connect:
      "In Palworld choose Join Multiplayer Game, paste this address at the bottom and connect.",
    settings: [
      "Difficulty, death penalty and PvP.",
      "EXP, capture and spawn rates, day/night speed.",
      "Changes are written to the server for you and apply after a restart.",
    ],
    console:
      "The live log plus Palworld's remote console. Try ShowPlayers, or Broadcast to message everyone.",
  },
};

const FALLBACK: FamilyCopy = {
  connect: "Give this address to your players — click it here to copy it.",
};

/** Families with their own named tour (distinct copy above). Everything else gets the generic tour. */
export const DEDICATED_GAME_TOURS = Object.keys(FAMILY);

/* ── the tour ──────────────────────────────────────────────────────────── */

export function buildGameTour(ctx: GameTourContext): TourDef {
  const fam = FAMILY[ctx.family] ?? FALLBACK;
  const g = ctx.gameName;
  const steps: TourStep[] = [];

  steps.push({
    id: "ready",
    title: `Your ${g} server is ready`,
    body: "It's built, online and yours. This 1-minute tour shows where everything lives — you can skip it, and replay it any time from “Take the tour”.",
    autoOnly: true,
    celebrate: true,
  });

  steps.push({
    id: "connect",
    title: "Your connect address",
    body: fam.connect,
    target: "game-connect",
    navigate: ["tab-overview"],
    placement: "bottom",
  });

  steps.push({
    id: "power",
    title: "Start, restart, stop",
    body: "These control the game itself. Most setting changes need a Restart to take effect — the status pill shows what's happening while it works.",
    target: "game-power",
    placement: "bottom",
  });

  steps.push({
    id: "vitals",
    title: "Live vitals",
    body: "Players, CPU, RAM and disk, updated as you watch. If RAM sits near the top, it's time for a bigger plan.",
    target: "game-vitals",
    placement: "bottom",
    optional: true,
  });

  steps.push({
    id: "tabs",
    title: "Everything else is a tab away",
    body: "This bar stays pinned while you scroll, so you can jump between Console, Files, Mods, Backups, Players and Settings from anywhere.",
    target: "game-tabs",
    placement: "bottom",
  });

  // Settings — the thing most people come looking for.
  if (ctx.hasGameSettings) {
    const bullets =
      fam.settings ??
      [
        ctx.variants.length > 1 ? `Server type: ${ctx.variants.join(", ")}.` : null,
        "Fields tagged RESTART apply after the next restart.",
      ].filter((b): b is string => !!b);
    steps.push({
      id: "game-settings",
      title: `${g} settings`,
      body: ctx.canApply
        ? "Change how your server plays, then press Save & apply — we write it to the server for you."
        : `We'll save these, but ${g} can't have them pushed into the running server yet — edit the config in Files and restart, or ask support and we'll do it.`,
      bullets,
      navigate: ["tab-settings", "section-game"],
      target: "game-settings",
      placement: "left",
    });
  } else {
    steps.push({
      id: "settings",
      title: "Settings",
      body: "Rename the server, auto-updates, network and access details, upgrades and billing all live here.",
      navigate: ["tab-settings"],
      target: "tab-settings",
      placement: "bottom",
    });
  }

  // Mods — only promise one-click installs where they work.
  steps.push(
    ctx.modsInstallable
      ? {
          id: "mods",
          title: ctx.family === "terraria" ? "Plugins" : "Mods & plugins",
          body: fam.mods ?? "Browse the catalogue and install with one click, then restart so the server loads it.",
          navigate: ["tab-mods"],
          target: "tab-panel",
          placement: "top",
        }
      : {
          id: "mods",
          title: "Mods & plugins",
          body: `One-click installs aren't available for ${g} yet. You can still add mods yourself: upload them in Files (or over SFTP) and restart.`,
          navigate: ["tab-mods"],
          target: "tab-mods",
          placement: "bottom",
        },
  );

  steps.push({
    id: "console",
    title: "Console",
    body:
      fam.console ??
      (ctx.rcon
        ? "The live server log plus a remote console — type server commands here and see the reply."
        : `The live server log — the first place to look if something isn't working. ${g} has no remote console, so commands are typed in-game by an admin.`),
    navigate: ["tab-console"],
    target: "tab-panel",
    placement: "top",
  });

  steps.push({
    id: "files",
    title: "Files",
    body: "Browse, edit, upload and download your server's files in the browser — configs, worlds, mods. Big uploads are easier over SFTP (details in Settings → Server access).",
    navigate: ["tab-files"],
    target: "tab-files",
    placement: "bottom",
  });

  steps.push({
    id: "players",
    title: "Players",
    body:
      fam.players ??
      (ctx.rcon
        ? "See who's online and kick or ban players, straight from the panel."
        : ctx.logTracked
          ? "The player list is read from the server log as people join and leave."
          : `${g} doesn't expose a remote console, so players are managed through its own config and whitelist files in Files.`),
    navigate: ["tab-players"],
    target: "tab-players",
    placement: "bottom",
  });

  if (ctx.family === "minecraft") {
    steps.push({
      id: "whitelist",
      title: "Whitelist & operators",
      body: "Add the players allowed to join, and make yourself an operator. The whitelist only takes effect once it's switched on in Settings.",
      navigate: ["tab-players", "players-whitelist"],
      target: "players-whitelist",
      placement: "bottom",
      optional: true,
    });
  }

  steps.push({
    id: "backups",
    title: "Backups",
    body:
      ctx.family === "minecraft"
        ? "Take a world archive before big changes, set automatic backups, and restore in a few clicks. Your Worlds are listed here too."
        : "Take a backup before big changes, set automatic backups, and restore in a few clicks. Backups are stored separately from your server's disk.",
    navigate: ["tab-backups"],
    target: "tab-backups",
    placement: "bottom",
  });

  steps.push({
    id: "schedules",
    title: "Schedules",
    body: ctx.rcon
      ? "Automatic restarts and timed console commands — a nightly restart keeps most servers fast."
      : "Automatic restarts on a timer — a nightly restart keeps most servers fast.",
    navigate: ["tab-schedules"],
    target: "tab-schedules",
    placement: "bottom",
  });

  steps.push({
    id: "network",
    title: "Address & domain",
    body: ctx.subdomain
      ? ctx.family === "minecraft"
        ? "Pick a free subdomain so players join with a name instead of an IP and port — or point your own domain here."
        : "Pick a subdomain so players join with a name instead of a raw IP. They'll still enter the port."
      : "Your connect address, plus the option to list your server in the public Server Directory.",
    navigate: ["tab-settings", "section-network"],
    target: "section-network",
    placement: "right",
    optional: true,
  });

  steps.push({
    id: "upgrade",
    title: "Need more power?",
    body: ctx.isFree
      ? "When you outgrow this server, Resources shows the paid plans you can move to."
      : "Move to a bigger plan or add a dedicated IP from Resources — your world comes with you.",
    navigate: ["tab-settings", "section-upgrade"],
    target: "section-upgrade",
    placement: "right",
    optional: true,
  });

  steps.push({
    id: "done",
    title: "You're all set",
    body: "Replay this tour any time from “Take the tour” at the top of this page. Stuck? Support is one click away under More.",
    navigate: ["tab-overview"],
    target: "tour-replay",
    placement: "bottom",
  });

  return { key: `game:${ctx.family}`, title: `${g} server tour`, steps };
}

