/**
 * VPS tour — written against components/customer/vpspanel/v2/* (VpsPanelShell
 * tabs, VpsHero, VpsPowerControls, VpsOverviewPanel's Quick connect,
 * VpsNetworkingPanel, VpsSettingsShell). Pure data.
 */

import type { TourDef } from "./types";

export type VpsTourContext = {
  /** Server has its own public IP (no NAT port forwards needed). */
  dedicatedIp: boolean;
  osName: string;
  isFree: boolean;
};

export function buildVpsTour(ctx: VpsTourContext): TourDef {
  return {
    key: "vps",
    title: "VPS tour",
    steps: [
      {
        id: "ready",
        title: "Your server is ready",
        body: `${ctx.osName} is installed and running. This 1-minute tour shows where everything lives — skip it any time, and replay it from “Take the tour”.`,
        autoOnly: true,
        celebrate: true,
      },
      {
        id: "ip",
        title: "Your server's address",
        body: ctx.dedicatedIp
          ? "This is your server's own dedicated IP. Click to copy it."
          : "This is the address you connect to. Click to copy it.",
        target: "vps-ip",
        navigate: ["tab-overview"],
        placement: "bottom",
      },
      {
        id: "power",
        title: "Power and terminal",
        body: "Start, stop and reboot from here. Terminal opens a shell in your browser — no SSH client needed.",
        target: "vps-power",
        placement: "bottom",
      },
      {
        id: "connect",
        title: "Connect with SSH or SFTP",
        body: "Copy the ready-made SSH or SFTP command. You sign in as root; the password is under Networking → Credentials.",
        target: "vps-quick-connect",
        placement: "top",
        optional: true,
      },
      {
        id: "tabs",
        title: "Everything else is a tab away",
        body: "This bar stays pinned while you scroll, so every part of your server is one click from anywhere.",
        target: "vps-tabs",
        placement: "bottom",
      },
      {
        id: "console",
        title: "Console",
        body: "A direct screen on your server that works even when SSH doesn't — the way back in if a firewall rule or config change locks you out.",
        navigate: ["tab-console"],
        target: "tab-console",
        placement: "bottom",
      },
      {
        id: "files",
        title: "Files",
        body: "Browse, edit, upload and download files in the browser while the server is running.",
        navigate: ["tab-files"],
        target: "tab-files",
        placement: "bottom",
      },
      {
        id: "services",
        title: "Services",
        body: "What's running inside the machine: websites and certificates, databases, one-click apps, and background services.",
        navigate: ["tab-services"],
        target: "tab-services",
        placement: "bottom",
      },
      {
        id: "backups",
        title: "Backups & snapshots",
        body: "Backups are full copies kept on separate storage; snapshots are instant restore points. Take a snapshot before risky changes.",
        navigate: ["tab-backups"],
        target: "tab-backups",
        placement: "bottom",
      },
      {
        id: "networking",
        title: "Networking",
        body: ctx.dedicatedIp
          ? "Your firewall rules and credentials live here. With a dedicated IP, every port is reachable directly — use the firewall to decide what's open."
          : "To make an app reachable from the internet (a website, a game), add a port forward here. Firewall rules and your root password live here too.",
        navigate: ["tab-networking"],
        target: "tab-networking",
        placement: "bottom",
      },
      {
        id: "resources",
        title: "Resize when you need to",
        body: ctx.isFree
          ? "Resources shows the paid plans you can move to when you outgrow this one."
          : "Add CPU, RAM, storage or a dedicated IP from Resources — every price is shown before you confirm.",
        navigate: ["tab-settings", "section-resources"],
        target: "section-resources",
        placement: "right",
        optional: true,
      },
      {
        id: "os",
        title: "Start fresh",
        body: "Reinstall the operating system here if you ever want a clean slate. It wipes the disk, so take a backup first.",
        navigate: ["tab-settings", "section-os"],
        target: "section-os",
        placement: "right",
        optional: true,
      },
      {
        id: "done",
        title: "You're all set",
        body: "Replay this tour any time from “Take the tour” at the top of this page. Questions? Support is in the menu on the left.",
        navigate: ["tab-overview"],
        target: "tour-replay",
        placement: "bottom",
      },
    ],
  };
}

