/**
 * DOM helpers for the tour engine. Client-only (called from effects).
 *
 * Targets are found by `data-tour="<id>"`. An element counts as present only
 * when it is actually laid out and visible — a tab that renders nothing at this
 * breakpoint, a `hidden lg:block` logo, or a `visibility:hidden` node all read
 * as "missing" so the engine can skip or fall back instead of spotlighting an
 * empty box at 0,0.
 */

export type Box = { x: number; y: number; w: number; h: number };

export function findTourEl(id: string): HTMLElement | null {
  if (typeof document === "undefined") return null;
  const all = document.querySelectorAll<HTMLElement>(`[data-tour="${cssEscape(id)}"]`);
  for (const el of all) if (isShown(el)) return el;
  return null;
}

function cssEscape(s: string): string {
  return typeof CSS !== "undefined" && CSS.escape ? CSS.escape(s) : s.replace(/["\\]/g, "\\$&");
}

/**
 * The element's on-screen box. `display: contents` wrappers (a cheap way to tag
 * a component without changing layout) have no box of their own, so they are
 * measured as the union of their children.
 */
export function boxOf(el: HTMLElement): Box | null {
  const style = getComputedStyle(el);
  if (style.display === "contents") {
    let x1 = Infinity, y1 = Infinity, x2 = -Infinity, y2 = -Infinity;
    for (const c of Array.from(el.children) as HTMLElement[]) {
      const b = boxOf(c);
      if (!b) continue;
      x1 = Math.min(x1, b.x); y1 = Math.min(y1, b.y);
      x2 = Math.max(x2, b.x + b.w); y2 = Math.max(y2, b.y + b.h);
    }
    return x1 === Infinity ? null : { x: x1, y: y1, w: x2 - x1, h: y2 - y1 };
  }
  const r = el.getBoundingClientRect();
  if (r.width < 1 || r.height < 1) return null;
  return { x: r.left, y: r.top, w: r.width, h: r.height };
}

export function isShown(el: HTMLElement): boolean {
  if (!el.isConnected) return false;
  const style = getComputedStyle(el);
  if (style.visibility === "hidden" || style.display === "none") return false;
  if (style.display !== "contents" && el.getClientRects().length === 0) return false;
  return boxOf(el) !== null;
}

/** Already-selected tab/section/sub-tab controls report it through ARIA. */
export function isActiveControl(el: HTMLElement): boolean {
  const cur = el.getAttribute("aria-current");
  if (cur && cur !== "false") return true;
  if (el.getAttribute("aria-pressed") === "true") return true;
  if (el.getAttribute("aria-selected") === "true") return true;
  return false;
}

export function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

/** Poll for a visible `[data-tour=id]` for up to `timeoutMs`. */
export async function waitForTourEl(
  id: string,
  timeoutMs: number,
  cancelled: () => boolean,
): Promise<HTMLElement | null> {
  const t0 = Date.now();
  for (;;) {
    if (cancelled()) return null;
    const el = findTourEl(id);
    if (el) return el;
    if (Date.now() - t0 >= timeoutMs) return null;
    await sleep(60);
  }
}

/**
 * Bring the target into view if any part of it is off-screen. Elements inside
 * a sticky header are always on screen, so they are never scrolled for (that
 * would yank the page to the top). Tall targets are aligned to their top.
 */
export function ensureInView(el: HTMLElement, reduced: boolean): void {
  const b = boxOf(el);
  if (!b) return;
  const vh = window.innerHeight;
  const fullyVisible = b.y >= 0 && b.y + b.h <= vh;
  if (fullyVisible) return;
  // A tall target already filling most of the screen from near the top is fine.
  if (b.h > vh * 0.7 && b.y >= 0 && b.y < vh * 0.6) return;
  el.scrollIntoView({ block: b.h > vh * 0.6 ? "start" : "center", inline: "nearest", behavior: reduced ? "auto" : "smooth" });
}

/** Mark everything except our own root inert while the tour is open (screen-reader + focus containment). */
export function setPageInert(except: HTMLElement, on: boolean): void {
  for (const child of Array.from(document.body.children) as HTMLElement[]) {
    if (child === except) continue;
    if (on) {
      if (!child.hasAttribute("inert")) {
        child.setAttribute("inert", "");
        child.setAttribute("data-nx-tour-inert", "");
      }
    } else if (child.hasAttribute("data-nx-tour-inert")) {
      child.removeAttribute("inert");
      child.removeAttribute("data-nx-tour-inert");
    }
  }
}

export const FOCUSABLE =
  'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

