/**
 * Where the step card goes relative to the spotlight. Pure (unit-tested in
 * test/tours-trigger.test.ts) — no DOM access.
 */

import type { TourPlacement } from "@/lib/tours/types";

export type Rect = { x: number; y: number; w: number; h: number };
export type Side = "top" | "bottom" | "left" | "right" | "center" | "sheet-top" | "sheet-bottom";

export type CardPos = {
  side: Side;
  x: number;
  y: number;
  /** Arrow offset along the card edge facing the target (px from the card's left/top), or null for no arrow. */
  arrow: number | null;
};

export const EDGE = 12;
export const GAP = 14;

/** Grow a target box by `pad` and clip it to the viewport (a tall panel is spotlit only where it is visible). */
export function spotRect(b: Rect, vw: number, vh: number, pad = 8): Rect {
  const x1 = Math.max(4, b.x - pad);
  const y1 = Math.max(4, b.y - pad);
  const x2 = Math.min(vw - 4, b.x + b.w + pad);
  const y2 = Math.min(vh - 4, b.y + b.h + pad);
  return { x: x1, y: y1, w: Math.max(0, x2 - x1), h: Math.max(0, y2 - y1) };
}

const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), Math.max(lo, hi));

export function placeCard(opts: {
  spot: Rect | null;
  card: { w: number; h: number };
  vw: number;
  vh: number;
  prefer?: TourPlacement;
  /** Phone layout: a bottom (or top) sheet instead of a floating card. */
  mobile: boolean;
}): CardPos {
  const { spot, card, vw, vh, mobile } = opts;
  if (mobile) {
    // The sheet sits at the bottom unless that would cover the target.
    if (spot && spot.y + spot.h > vh - card.h - EDGE - GAP && spot.y > card.h + EDGE + GAP) {
      return { side: "sheet-top", x: EDGE, y: EDGE, arrow: null };
    }
    return { side: "sheet-bottom", x: EDGE, y: vh - card.h - EDGE, arrow: null };
  }
  if (!spot) {
    return { side: "center", x: (vw - card.w) / 2, y: Math.max(EDGE, (vh - card.h) / 2), arrow: null };
  }

  const cx = spot.x + spot.w / 2;
  const cy = spot.y + spot.h / 2;
  const fits: Record<"top" | "bottom" | "left" | "right", boolean> = {
    bottom: spot.y + spot.h + GAP + card.h <= vh - EDGE,
    top: spot.y - GAP - card.h >= EDGE,
    right: spot.x + spot.w + GAP + card.w <= vw - EDGE,
    left: spot.x - GAP - card.w >= EDGE,
  };
  const opposite = { top: "bottom", bottom: "top", left: "right", right: "left" } as const;
  const prefer = opts.prefer && opts.prefer !== "auto" ? opts.prefer : null;
  const order: ("top" | "bottom" | "left" | "right")[] = prefer
    ? [prefer, opposite[prefer], ...(["bottom", "top", "right", "left"] as const).filter((s) => s !== prefer && s !== opposite[prefer])]
    : ["bottom", "top", "right", "left"];
  const side = order.find((s) => fits[s]);

  if (side === "bottom" || side === "top") {
    const x = clamp(cx - card.w / 2, EDGE, vw - card.w - EDGE);
    const y = side === "bottom" ? spot.y + spot.h + GAP : spot.y - GAP - card.h;
    return { side, x, y, arrow: clamp(cx - x, 22, card.w - 22) };
  }
  if (side === "left" || side === "right") {
    const y = clamp(cy - card.h / 2, EDGE, vh - card.h - EDGE);
    const x = side === "right" ? spot.x + spot.w + GAP : spot.x - GAP - card.w;
    return { side, x, y, arrow: clamp(cy - y, 22, card.h - 22) };
  }
  // Nothing fits beside a huge target: float over its lower part, centred.
  return { side: "center", x: clamp(cx - card.w / 2, EDGE, vw - card.w - EDGE), y: Math.max(EDGE, vh - card.h - 24), arrow: null };
}

