"use client";

/**
 * The tour engine: spotlight + animated ring and pointer + step card.
 *
 * Lazy-loaded by TourLauncher (next/dynamic, ssr:false) only when a tour is
 * actually opening, so pages pay nothing for it otherwise.
 *
 * Stacking: everything renders into a <div> appended to document.body via
 * createPortal. It can NOT live inside the panel — the game/VPS/hosting heroes
 * sit in a sticky `backdrop-blur-xl` wrapper and several cards are
 * `card-glass`, and a `backdrop-filter` ancestor becomes the containing block
 * for `position: fixed` descendants (CLAUDE.md), which would pin the overlay to
 * a card instead of the viewport.
 *
 * Accessibility: the card is a labelled modal dialog; the rest of the page is
 * made `inert` while it is open; Tab is trapped inside the card; Esc skips;
 * ←/→ move between steps; focus returns to where it was on close; each step is
 * announced through a polite live region. prefers-reduced-motion turns off
 * every transition, the pulse, the pointer bob, the confetti and smooth scroll.
 */

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { TourStep } from "@/lib/tours/types";
import {
  boxOf, ensureInView, findTourEl, FOCUSABLE, isActiveControl, setPageInert, sleep, waitForTourEl, type Box,
} from "./dom";
import { placeCard, spotRect, type CardPos } from "./placement";

export type TourOverlayProps = {
  title: string;
  steps: TourStep[];
  startAt: number;
  onStep: (index: number) => void;
  onFinish: (index: number) => void;
  onDismiss: (index: number) => void;
  onOptOut: (index: number) => void;
  /** Hide the "don't show tours again" link (e.g. no persistence while impersonating). */
  canOptOut: boolean;
};

const MOBILE_Q = "(max-width: 639px)";
const REDUCED_Q = "(prefers-reduced-motion: reduce)";
const TARGET_WAIT_MS = 1600;
const NAV_WAIT_MS = 1200;

function useMedia(q: string): boolean {
  const [m, setM] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia(q);
    const on = () => setM(mq.matches);
    on();
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, [q]);
  return m;
}

type Resolved = { index: number; el: HTMLElement | null };

export default function TourOverlay({
  title, steps, startAt, onStep, onFinish, onDismiss, onOptOut, canOptOut,
}: TourOverlayProps) {
  const reduced = useMedia(REDUCED_Q);
  const mobile = useMedia(MOBILE_Q);
  const [root, setRoot] = useState<HTMLElement | null>(null);
  const [index, setIndex] = useState(() => Math.min(Math.max(0, startAt), steps.length - 1));
  const [resolved, setResolved] = useState<Resolved | null>(null);
  const [box, setBox] = useState<Box | null>(null);
  const [vp, setVp] = useState({ w: 1280, h: 800 });
  const [cardSize, setCardSize] = useState({ w: 360, h: 220 });
  const dir = useRef<1 | -1>(1);
  const cardRef = useRef<HTMLDivElement>(null);
  const primaryRef = useRef<HTMLButtonElement>(null);
  const returnFocus = useRef<Element | null>(null);

  /* ── portal root + page inert ───────────────────────────────────────── */
  useEffect(() => {
    returnFocus.current = document.activeElement;
    const el = document.createElement("div");
    el.id = "nx-tour-root";
    document.body.appendChild(el);
    setRoot(el);
    setPageInert(el, true);
    return () => {
      setPageInert(el, false);
      el.remove();
      const back = returnFocus.current as HTMLElement | null;
      if (back && typeof back.focus === "function" && back.isConnected) back.focus({ preventScroll: true });
    };
  }, []);

  /* ── resolve the current step: navigate, find target, scroll ────────── */
  useEffect(() => {
    let cancelled = false;
    const isCancelled = () => cancelled;
    setResolved(null);
    (async () => {
      let i = index;
      // Walk in the direction of travel past optional steps whose target is missing.
      for (;;) {
        const step = steps[i];
        if (!step) return;
        if (root) setPageInert(root, false); // programmatic clicks must reach the page
        for (const nav of step.navigate ?? []) {
          const ctl = await waitForTourEl(nav, NAV_WAIT_MS, isCancelled);
          if (cancelled) return;
          if (ctl && !isActiveControl(ctl)) {
            ctl.click();
            await sleep(reduced ? 60 : 160);
          }
        }
        if (root) setPageInert(root, true);
        if (cancelled) return;
        const el = step.target ? await waitForTourEl(step.target, TARGET_WAIT_MS, isCancelled) : null;
        if (cancelled) return;
        if (step.target && !el && step.optional) {
          const next = i + dir.current;
          if (next < 0 || next >= steps.length) {
            // Nothing left that way — show this one centred rather than ending abruptly.
            setResolved({ index: i, el: null });
            if (i !== index) setIndex(i);
            return;
          }
          i = next;
          continue;
        }
        if (el) {
          ensureInView(el, reduced);
          if (!reduced) await sleep(220);
        }
        if (cancelled) return;
        if (i !== index) {
          // Skipped ahead/back: commit the real index without re-running navigation.
          setIndex(i);
        }
        setResolved({ index: i, el });
        return;
      }
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [index, root]);

  const shownIndex = resolved?.index ?? index;
  const step = steps[shownIndex];
  const ready = resolved !== null && resolved.index === index;

  /* Persist the step that is actually on screen. */
  useEffect(() => {
    if (ready) onStep(index);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ready, index]);

  /* ── follow the target every frame (sticky headers, smooth scroll, layout shifts) ── */
  useEffect(() => {
    if (!ready) return;
    let raf = 0;
    let last = "";
    const tick = () => {
      const w = window.innerWidth, h = window.innerHeight;
      let b: Box | null = null;
      const el = resolved?.el;
      if (el) {
        const live = el.isConnected ? el : step?.target ? findTourEl(step.target) : null;
        b = live ? boxOf(live) : null;
      }
      const key = b ? `${w},${h},${b.x | 0},${b.y | 0},${b.w | 0},${b.h | 0}` : `${w},${h},none`;
      if (key !== last) {
        last = key;
        setVp({ w, h });
        setBox(b);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [ready, resolved, step?.target]);

  /* ── measure the card so placement uses its real size ───────────────── */
  useLayoutEffect(() => {
    const el = cardRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => {
      const r = el.getBoundingClientRect();
      setCardSize((s) => (Math.abs(s.w - r.width) > 1 || Math.abs(s.h - r.height) > 1 ? { w: r.width, h: r.height } : s));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [root, ready]);

  /* ── focus the primary action whenever a step lands ─────────────────── */
  useEffect(() => {
    if (ready) primaryRef.current?.focus({ preventScroll: true });
  }, [ready, index]);

  const last = index >= steps.length - 1;
  const go = useCallback((d: 1 | -1) => {
    if (!ready) return;
    if (d === 1 && last) { onFinish(index); return; }
    if (d === -1 && index === 0) return;
    dir.current = d;
    setIndex((i) => i + d);
  }, [ready, last, index, onFinish]);

  const dismiss = useCallback(() => onDismiss(index), [index, onDismiss]);

  /* ── keyboard: Esc, arrows, focus trap ──────────────────────────────── */
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") { e.preventDefault(); dismiss(); return; }
      if (e.key === "ArrowRight") { e.preventDefault(); go(1); return; }
      if (e.key === "ArrowLeft") { e.preventDefault(); go(-1); return; }
      if (e.key === "Tab" && cardRef.current) {
        const f = Array.from(cardRef.current.querySelectorAll<HTMLElement>(FOCUSABLE));
        if (f.length === 0) return;
        const first = f[0]!, lastEl = f[f.length - 1]!;
        const a = document.activeElement;
        if (!cardRef.current.contains(a)) { e.preventDefault(); first.focus(); return; }
        if (e.shiftKey && a === first) { e.preventDefault(); lastEl.focus(); }
        else if (!e.shiftKey && a === lastEl) { e.preventDefault(); first.focus(); }
      }
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [go, dismiss]);

  /* ── geometry ───────────────────────────────────────────────────────── */
  const spot = box ? spotRect(box, vp.w, vp.h) : null;
  const pos: CardPos = useMemo(
    () => placeCard({ spot, card: cardSize, vw: vp.w, vh: vp.h, prefer: step?.placement, mobile }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [spot?.x, spot?.y, spot?.w, spot?.h, cardSize.w, cardSize.h, vp.w, vp.h, step?.placement, mobile],
  );
  const smallTarget = !!spot && spot.w * spot.h < vp.w * vp.h * 0.2;

  if (!root || !step) return null;

  const total = steps.length;
  const titleId = "nx-tour-title";
  const bodyId = "nx-tour-body";
  const anim = !reduced;

  const cardStyle: React.CSSProperties = mobile
    ? { left: 12, right: 12, top: pos.side === "sheet-top" ? 12 : undefined, bottom: pos.side === "sheet-bottom" ? "calc(12px + env(safe-area-inset-bottom))" : undefined }
    : { left: pos.x, top: pos.y, width: 372 };

  return createPortal(
    <div className="nx-tour" data-reduced={reduced ? "1" : "0"} style={{ position: "fixed", inset: 0, zIndex: 2147483000 }}>
      <style>{TOUR_CSS}</style>

      {/* Click shield: the page underneath is not interactive while touring. */}
      <div aria-hidden className="absolute inset-0" style={{ cursor: "default" }} onClick={() => primaryRef.current?.focus()} />

      {/* Dim + spotlight. With no target, a plain dim. */}
      {spot ? (
        <div
          aria-hidden
          className={"nx-tour-spot " + (anim ? "nx-tour-anim" : "")}
          style={{ left: spot.x, top: spot.y, width: spot.w, height: spot.h }}
        >
          <span className={"nx-tour-ring " + (anim ? "nx-tour-pulse" : "")} />
        </div>
      ) : (
        <div aria-hidden className={"nx-tour-dim " + (anim ? "nx-tour-fade" : "")} />
      )}

      {/* Animated pointer, for targets small enough that "this one" needs saying. */}
      {spot && smallTarget && ready && (
        <span
          aria-hidden
          className={"nx-tour-pointer " + (anim ? "nx-tour-anim nx-tour-bob" : "")}
          style={{ left: Math.min(vp.w - 40, spot.x + spot.w - 14), top: Math.min(vp.h - 40, spot.y + spot.h - 10) }}
        >
          <svg width="30" height="30" viewBox="0 0 24 24" fill="none">
            <path d="M5 3l13 6.5-5.6 1.6L10 17 5 3z" fill="url(#nxTourG)" stroke="#fff" strokeWidth="1.4" strokeLinejoin="round" />
            <defs>
              <linearGradient id="nxTourG" x1="5" y1="3" x2="18" y2="17">
                <stop stopColor="#3b6be8" /><stop offset="1" stopColor="#7b3fef" />
              </linearGradient>
            </defs>
          </svg>
        </span>
      )}

      <p aria-live="polite" className="sr-only">
        {ready ? `Step ${index + 1} of ${total}: ${step.title}` : ""}
      </p>

      <div
        ref={cardRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        aria-describedby={bodyId}
        aria-busy={!ready}
        key={anim ? index : undefined}
        className={"nx-tour-card " + (anim ? "nx-tour-enter " : "") + (mobile ? "nx-tour-sheet" : "")}
        style={{ ...cardStyle, opacity: ready ? 1 : 0.0001 }}
      >
        {!mobile && pos.arrow !== null && (pos.side === "top" || pos.side === "bottom" || pos.side === "left" || pos.side === "right") && (
          <span
            aria-hidden
            className="nx-tour-arrow"
            style={
              pos.side === "bottom" ? { top: -6, left: pos.arrow - 6 }
              : pos.side === "top" ? { bottom: -6, left: pos.arrow - 6 }
              : pos.side === "right" ? { left: -6, top: pos.arrow - 6 }
              : { right: -6, top: pos.arrow - 6 }
            }
          />
        )}

        {step.celebrate && <Celebrate anim={anim} />}

        <div className="flex items-start gap-3">
          <div className="min-w-0 flex-1">
            <p className="text-[10.5px] font-bold uppercase tracking-[0.16em] text-[#7fd8ff]">
              {title} · {index + 1}/{total}
            </p>
            <h2 id={titleId} className="mt-1 text-[16.5px] font-extrabold leading-snug tracking-[-0.01em] text-white">
              {step.title}
            </h2>
          </div>
          <button
            type="button"
            onClick={dismiss}
            aria-label="Close tour"
            className="-mr-1 -mt-1 grid h-8 w-8 flex-none place-items-center rounded-[9px] text-[#9fb0d6] transition hover:bg-white/10 hover:text-white"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round"><path d="M6 6l12 12M18 6L6 18" /></svg>
          </button>
        </div>

        <div id={bodyId}>
          <p className="mt-2 text-[13.5px] leading-relaxed text-[#c9d4ee]">{step.body}</p>
          {step.bullets && step.bullets.length > 0 && (
            <ul className="mt-2.5 flex flex-col gap-1.5">
              {step.bullets.map((b) => (
                <li key={b} className="flex gap-2 text-[12.5px] leading-snug text-[#b8c5e4]">
                  <span aria-hidden className="mt-[6px] h-[5px] w-[5px] flex-none rounded-full bg-[#5fd0ff]" />
                  <span>{b}</span>
                </li>
              ))}
            </ul>
          )}
          {!spot && step.target && ready && !step.celebrate && (
            <p className="mt-2 text-[11.5px] text-[#8c9bc0]">This part of the panel isn&apos;t showing right now, so there&apos;s nothing to point at.</p>
          )}
        </div>

        {/* progress dots */}
        <div className="mt-4 flex items-center gap-1.5" aria-hidden>
          {steps.map((s, i) => (
            <span
              key={s.id}
              className={"h-[6px] rounded-full " + (anim ? "transition-all duration-300 " : "") + (i === index ? "w-[18px] bg-[linear-gradient(90deg,#3b6be8,#7b3fef)]" : i < index ? "w-[6px] bg-[#5fd0ff]/70" : "w-[6px] bg-white/15")}
            />
          ))}
        </div>

        <div className="mt-4 flex items-center gap-2">
          <button type="button" onClick={dismiss}
                  className="rounded-[10px] px-2.5 py-2 text-[12.5px] font-semibold text-[#9fb0d6] transition hover:text-white">
            {step.celebrate ? "Not now" : "Skip tour"}
          </button>
          <span className="flex-1" />
          {index > 0 && !step.celebrate && (
            <button type="button" onClick={() => go(-1)} disabled={!ready}
                    className="rounded-[10px] border border-white/15 bg-white/[0.04] px-3.5 py-2 text-[13px] font-semibold text-[#dbe4fa] transition hover:border-white/30 hover:text-white disabled:opacity-50">
              Back
            </button>
          )}
          <button
            ref={primaryRef}
            type="button"
            onClick={() => go(1)}
            disabled={!ready}
            className="rounded-[10px] bg-[linear-gradient(120deg,#3b6be8,#7b3fef)] px-4 py-2 text-[13px] font-bold text-white shadow-[0_6px_22px_-8px_rgba(123,63,239,.9)] transition hover:brightness-110 disabled:opacity-60"
          >
            {last ? "Finish" : step.celebrate ? "Show me around" : "Next"}
          </button>
        </div>

        {canOptOut && (
          <div className="mt-3 border-t border-white/10 pt-2.5 text-center">
            <button type="button" onClick={() => onOptOut(index)}
                    className="text-[11.5px] font-medium text-[#8c9bc0] underline-offset-2 transition hover:text-white hover:underline">
              Don&apos;t show tours again
            </button>
          </div>
        )}
      </div>
    </div>,
    root,
  );
}

function Celebrate({ anim }: { anim: boolean }) {
  const bits = Array.from({ length: 16 }, (_, i) => i);
  const colors = ["#3b6be8", "#7b3fef", "#5fd0ff", "#c33bea", "#34d399"];
  return (
    <div className="relative mb-3 flex justify-center pt-1" aria-hidden>
      <span className={"nx-tour-check " + (anim ? "nx-tour-pop" : "")}>
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5" /></svg>
      </span>
      {anim && bits.map((i) => (
        <span
          key={i}
          className="nx-tour-confetti"
          style={{
            background: colors[i % colors.length],
            ["--a" as string]: `${(360 / bits.length) * i}deg`,
            ["--d" as string]: `${48 + (i % 3) * 14}px`,
            animationDelay: `${(i % 4) * 30}ms`,
          } as React.CSSProperties}
        />
      ))}
    </div>
  );
}

/* Top-level @keyframes only — CLAUDE.md: keyframes nested inside a style rule
   are silently dropped. Everything is namespaced nx-tour-*. */
const TOUR_CSS = `
