@keyframes nxTourFade { from { opacity: 0; } to { opacity: 1; } }
@keyframes nxTourPop { 0% { transform: scale(.4); opacity: 0; } 60% { transform: scale(1.12); opacity: 1; } 100% { transform: scale(1); } }
@keyframes nxTourBurst { 0% { transform: rotate(var(--a)) translateY(0) scale(1); opacity: 1; } 100% { transform: rotate(var(--a)) translateY(calc(-1 * var(--d))) scale(.4); opacity: 0; } }
.nx-tour { font-family: inherit; }
.nx-tour .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.nx-tour-dim { position: absolute; inset: 0; background: rgba(2,6,20,.66); }
.nx-tour-spot { position: absolute; border-radius: 14px; box-shadow: 0 0 0 9999px rgba(2,6,20,.66); pointer-events: none; }
.nx-tour-ring { position: absolute; inset: 0; border-radius: inherit; border: 2px solid #5fd0ff; box-shadow: 0 0 0 0 rgba(95,208,255,.5), 0 0 24px -4px rgba(123,63,239,.85); }
.nx-tour-anim { transition: left .32s cubic-bezier(.2,.8,.2,1), top .32s cubic-bezier(.2,.8,.2,1), width .32s cubic-bezier(.2,.8,.2,1), height .32s cubic-bezier(.2,.8,.2,1); }
.nx-tour-pulse { animation: nxTourPulse 1.8s ease-out infinite; }
.nx-tour-pointer { position: absolute; pointer-events: none; filter: drop-shadow(0 4px 10px rgba(0,0,0,.5)); }
.nx-tour-bob { animation: nxTourBob 1.3s ease-in-out infinite; }
.nx-tour-card { position: absolute; max-width: calc(100vw - 24px); border-radius: 16px; padding: 16px 16px 14px; color: #fff;
  background: linear-gradient(180deg, rgba(16,26,58,.98), rgba(7,13,32,.98)); border: 1px solid rgba(139,92,255,.45);
  box-shadow: 0 24px 60px -18px rgba(0,0,0,.8), 0 0 0 1px rgba(95,208,255,.08), 0 0 42px -12px rgba(123,63,239,.7); }
