.nx-tour-arrow { position: absolute; width: 12px; height: 12px; transform: rotate(45deg); background: #101a3a; border-left: 1px solid rgba(139,92,255,.45); border-top: 1px solid rgba(139,92,255,.45); }
.nx-tour-card .nx-tour-arrow[style*="bottom"] { transform: rotate(225deg); background: #0a1229; }
.nx-tour-card .nx-tour-arrow[style*="right"] { transform: rotate(135deg); }
.nx-tour-card .nx-tour-arrow[style*="left: -6px"] { transform: rotate(-45deg); }
.nx-tour-check { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 16px; background: linear-gradient(135deg,#3b6be8,#7b3fef); box-shadow: 0 0 30px -6px rgba(123,63,239,.95); }
.nx-tour-pop { animation: nxTourPop .5s cubic-bezier(.2,.9,.3,1.3) both; }
.nx-tour-confetti { position: absolute; left: 50%; top: 30px; width: 6px; height: 10px; margin-left: -3px; border-radius: 2px; animation: nxTourBurst .9s ease-out both; }
@media (prefers-reduced-motion: reduce) {
  .nx-tour *, .nx-tour *::before, .nx-tour *::after { animation: none !important; transition: none !important; }
}
`;

