"use client";

/**
 * The tiny, always-loaded half of the tour system: the "Take the tour" button,
 * the auto-start trigger, and persistence calls. The engine itself
 * (TourOverlay) is a separate lazy chunk, fetched only when a tour opens.
 *
 * Hydration-safe by construction: the server renders only the button; whether
 * to auto-open is decided server-side (lib/tours/server.ts) and passed in as a
 * prop, and the overlay mounts in an effect after hydration.
 *
 * Anything else on the page can open the tour too:
 *   window.dispatchEvent(new CustomEvent("nx-tour:start", { detail: { key } }))
 */

import dynamic from "next/dynamic";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { TourDef } from "@/lib/tours/types";
import { optOutOfTours, recordTourEvent } from "@/lib/tours/actions";

const TourOverlay = dynamic(() => import("./TourOverlay"), { ssr: false });

export const TOUR_START_EVENT = "nx-tour:start";

type Mode = { kind: "auto" | "replay"; startAt: number };

export function TourLauncher({
  tour, autoStart, resumeAt = 0, fresh = true, persist, showButton = true, className = "",
}: {
  tour: TourDef;
  autoStart: boolean;
  resumeAt?: number;
  /** A brand-new run, as opposed to resuming an interrupted one. */
  fresh?: boolean;
  /** Write progress (owner, not impersonating). */
  persist: boolean;
  showButton?: boolean;
  className?: string;
}) {
  const [mode, setMode] = useState<Mode | null>(null);
  const started = useRef(false);

  /* Auto runs include the one-time "it's ready" step; replays skip it. Both
     index into their own list, and only auto runs persist `lastStep`, so a
     resume index always refers to the auto list. */
  const steps = useMemo(
    () => (mode?.kind === "replay" ? tour.steps.filter((s) => !s.autoOnly) : tour.steps),
    [mode?.kind, tour.steps],
  );

  const send = useCallback(
    (ev: { type: "start" | "step" | "complete" | "dismiss"; step?: number }) => {
      if (!persist) return;
