"use client";

/**
 * The tiny, always-loaded half of the tour system: the "Take the tour" button,
 * the auto-start trigger, and persistence calls. The engine itself
 * (TourOverlay) is a separate lazy chunk, fetched only when a tour opens.
 *
 * Hydration-safe by construction: the server renders only the button; whether
 * to auto-open is decided server-side (lib/tours/server.ts) and passed in as a
 * prop, and the overlay mounts in an effect after hydration.
 *
 * Anything else on the page can open the tour too:
 *   window.dispatchEvent(new CustomEvent("nx-tour:start", { detail: { key } }))
 */

import dynamic from "next/dynamic";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { TourDef } from "@/lib/tours/types";
import { optOutOfTours, recordTourEvent } from "@/lib/tours/actions";

const TourOverlay = dynamic(() => import("./TourOverlay"), { ssr: false });

export const TOUR_START_EVENT = "nx-tour:start";

type Mode = { kind: "auto" | "replay"; startAt: number };

export function TourLauncher({
  tour, autoStart, resumeAt = 0, fresh = true, persist, showButton = true, className = "",
}: {
  tour: TourDef;
  autoStart: boolean;
  resumeAt?: number;
  /** A brand-new run, as opposed to resuming an interrupted one. */
  fresh?: boolean;
  /** Write progress (owner, not impersonating). */
  persist: boolean;
  showButton?: boolean;
  className?: string;
}) {
  const [mode, setMode] = useState<Mode | null>(null);
  const started = useRef(false);

  /* Auto runs include the one-time "it's ready" step; replays skip it. Both
     index into their own list, and only auto runs persist `lastStep`, so a
     resume index always refers to the auto list. */
  const steps = useMemo(
    () => (mode?.kind === "replay" ? tour.steps.filter((s) => !s.autoOnly) : tour.steps),
    [mode?.kind, tour.steps],
  );

  const send = useCallback(
    (ev: { type: "start" | "step" | "complete" | "dismiss"; step?: number }) => {
      if (!persist) return;
      void recordTourEvent(tour.key, ev).catch(() => { /* a lost write only means the tour may show again */ });
    },
    [persist, tour.key],
  );

  /* Auto-start once, after the panel has hydrated and laid out. */
  useEffect(() => {
    if (!autoStart || started.current) return;
    started.current = true;
    const t = setTimeout(() => {
      const startAt = fresh ? 0 : Math.min(resumeAt, tour.steps.length - 1);
      setMode({ kind: "auto", startAt });
      send({ type: "start" });
    }, 700);
    return () => clearTimeout(t);
  }, [autoStart, fresh, resumeAt, tour.steps.length, send]);

  const replay = useCallback(() => {
    setMode({ kind: "replay", startAt: 0 });
  }, []);

  useEffect(() => {
    const on = (e: Event) => {
      const key = (e as CustomEvent<{ key?: string }>).detail?.key;
      if (!key || key === tour.key) replay();
    };
    window.addEventListener(TOUR_START_EVENT, on);
    return () => window.removeEventListener(TOUR_START_EVENT, on);
  }, [replay, tour.key]);

  const close = () => setMode(null);

  return (
    <>
      {showButton && (
        <button
          type="button"
          data-tour="tour-replay"
          onClick={replay}
          className={
            "inline-flex items-center gap-1.5 rounded-[10px] border border-[#8b5cff]/40 bg-[#7b3fef]/10 px-3 py-1.5 text-[12px] font-semibold text-[#c4a6ff] transition hover:border-[#8b5cff]/70 hover:text-white " +
            className
          }
        >
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <circle cx="12" cy="12" r="9.5" /><path d="M9.6 9.3a2.5 2.5 0 1 1 3.4 2.4c-.6.3-1 .8-1 1.5v.4" /><path d="M12 17h.01" />
          </svg>
          Take the tour
        </button>
      )}
      {mode && steps.length > 0 && (
        <TourOverlay
          key={`${mode.kind}-${mode.startAt}`}
          title={tour.title}
          steps={steps}
          startAt={mode.startAt}
          canOptOut={persist}
          onStep={(i) => { if (mode.kind === "auto") send({ type: "step", step: i }); }}
          onFinish={(i) => { send({ type: "complete", step: mode.kind === "auto" ? i : undefined }); close(); }}
          onDismiss={(i) => { send({ type: "dismiss", step: mode.kind === "auto" ? i : undefined }); close(); }}
          onOptOut={(i) => {
            if (persist) void optOutOfTours(tour.key, mode.kind === "auto" ? i : undefined).catch(() => {});
            close();
          }}
        />
      )}
    </>
  );
}

