/**
 * Server Component mount for a Server's dashboard (VPS or game panel).
 *
 * Decides the serviceKey (vps | game:<family>), builds the tour from the REAL
 * capabilities of this server's family, reads the viewer's progress, and
 * renders the client launcher (a "Take the tour" button + auto-start).
 *
 * Mounted once per branch in app/dashboard/servers/[id]/page.tsx, AFTER the
 * provisioning interstitial early-return — so a server that is still building
 * (or showing the post-payment "it's live" screen) never gets a tour.
 */

import { TourLauncher } from "./TourLauncher";
import { tourStateFor } from "@/lib/tours/server";
import { serviceKeyForServer } from "@/lib/tours/trigger";
import { buildGameTour } from "@/lib/tours/game";
import { buildVpsTour } from "@/lib/tours/vps";
import { canApplyConfig, schemaFor } from "@/lib/game-config";
import { controlSpec } from "@/lib/game-control";
import { INSTALLABLE_FAMILIES } from "@/lib/mod-install-support";
import { GAME_DISPLAY, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "@/lib/games";

export type ServerTourInput = {
  id: string;
  userId: string;
  status: string;
  createdAt: Date;
  isFree: boolean;
  gamePlanId: string | null;
  osTemplate: { family: string | null; name: string };
  gamePlan?: { gameFamily: string | null } | null;
  dedicatedIp?: unknown | null;
};

export async function ServerTour({
  server, isGame, className,
}: {
  server: ServerTourInput;
  isGame: boolean;
  className?: string;
}) {
  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family ?? "").toLowerCase();
  const serviceKey = serviceKeyForServer({ isGame, family });

  const tour =
    serviceKey === "vps"
      ? buildVpsTour({ dedicatedIp: !!server.dedicatedIp, osName: server.osTemplate.name, isFree: server.isFree })
      : (() => {
          const schema = schemaFor(family);
          return buildGameTour({
            family,
            gameName: GAME_DISPLAY[family as GameFamily]?.name ?? server.osTemplate.name,
            hasGameSettings: !!(server.gamePlanId && schema),
            canApply: canApplyConfig(family),
            variants: schema?.variants.map((v) => v.label) ?? [],
            hasVersion: !!schema?.fields.some((f) => f.key === "VERSION"),
            rcon: controlSpec(family)?.rcon === "source",
            // Same rule GamePanelShell uses for its log-tracked players view.
            logTracked: family === "valheim",
            modsInstallable: INSTALLABLE_FAMILIES.has(family),
            subdomain:
              family === "minecraft" || family === "bedrock" || HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily),
            isFree: server.isFree,
          });
        })();

  const state = await tourStateFor({
    serviceKey,
    ownerId: server.userId,
    ready: server.status === "RUNNING",
    createdAt: server.createdAt,
  });

  return (
    <TourLauncher
      tour={tour}
      autoStart={state.autoStart}
      resumeAt={state.resumeAt}
      fresh={state.fresh}
      persist={state.persist}
      className={className}
    />
  );
}

