import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import {
  applyTourEvent,
  isValidServiceKey,
  serviceKeyForServer,
  shouldAutoStart,
  AUTO_START_MAX_AGE_DAYS,
  MAX_STEP,
  type ProgressRow,
} from "../lib/tours/trigger.ts";
import { buildGameTour, type GameTourContext } from "../lib/tours/game.ts";
import { buildVpsTour } from "../lib/tours/vps.ts";
import { buildHostingTour } from "../lib/tours/hosting.ts";
import { placeCard, spotRect } from "../components/nx/tour/placement.ts";

/**
 * First-run tours (lib/tours, components/nx/tour). Pure logic only — the
 * server actions are thin wrappers around applyTourEvent + one upsert, and the
 * engine is exercised end-to-end with Playwright (see docs/TOURS.md).
 */

const NOW = new Date("2026-10-01T12:00:00Z");
const fresh = new Date("2026-09-30T12:00:00Z");

const base = {
  isOwner: true,
  impersonating: false,
  ready: true,
  progress: null,
  optedOut: false,
  createdAt: fresh,
  now: NOW,
};

/* ── serviceKey ─────────────────────────────────────────────────────────── */

test("serviceKey is per service, not per server", () => {
  assert.equal(serviceKeyForServer({ isGame: true, family: "minecraft" }), "game:minecraft");
  assert.equal(serviceKeyForServer({ isGame: true, family: "Valheim" }), "game:valheim");
  assert.equal(serviceKeyForServer({ isGame: false, family: "ubuntu" }), "vps");
  // A game server whose family is unknown/missing falls back to the VPS tour rather than an invalid key.
  assert.equal(serviceKeyForServer({ isGame: true, family: null }), "vps");
  assert.equal(serviceKeyForServer({ isGame: true, family: "bad key!" }), "vps");
});

test("only allow-listed serviceKeys are valid", () => {
  for (const k of ["vps", "hosting", "email", "domain", "game:minecraft", "game:sdtd", "game:plutoniumt4", "*"]) {
    assert.ok(isValidServiceKey(k), k);
  }
  for (const k of ["", "VPS", "game:", "game:Minecraft", "game:../x", "game:a", "admin", 5, null, `game:${"x".repeat(40)}`]) {
    assert.ok(!isValidServiceKey(k), String(k));
  }
});

/* ── auto-start ─────────────────────────────────────────────────────────── */

test("first visit of a ready server with no progress auto-starts at step 0", () => {
  assert.deepEqual(shouldAutoStart(base), { start: true, resumeAt: 0, fresh: true });
});

test("a second server of the same service does not retrigger (row exists)", () => {
  for (const status of ["COMPLETED", "DISMISSED"]) {
    const d = shouldAutoStart({ ...base, progress: { status } });
    assert.equal(d.start, false, status);
  }
});

test("an interrupted run (STARTED) resumes where it was", () => {
  assert.deepEqual(shouldAutoStart({ ...base, progress: { status: "STARTED" }, lastStep: 5 }), {
    start: true, resumeAt: 5, fresh: false,
  });
});

test("never auto-starts while impersonating, for a non-owner, before ready, behind the interstitial, or after opt-out", () => {
  assert.equal(shouldAutoStart({ ...base, impersonating: true }).start, false);
  assert.equal(shouldAutoStart({ ...base, isOwner: false }).start, false);
  assert.equal(shouldAutoStart({ ...base, ready: false }).start, false);
  assert.equal(shouldAutoStart({ ...base, interstitial: true }).start, false);
  assert.equal(shouldAutoStart({ ...base, optedOut: true }).start, false);
  // Impersonation wins even over an interrupted run.
  assert.equal(shouldAutoStart({ ...base, impersonating: true, progress: { status: "STARTED" } }).start, false);
});

test("a long-lived server (pre-launch fleet) is not greeted with 'it's ready'", () => {
  const old = new Date(NOW.getTime() - (AUTO_START_MAX_AGE_DAYS + 1) * 86_400_000);
  assert.deepEqual(shouldAutoStart({ ...base, createdAt: old }), { start: false, reason: "too-old" });
});

/* ── persistence reducer ────────────────────────────────────────────────── */

test("start → step → complete", () => {
  let r = applyTourEvent(null, { type: "start" }, NOW);
  assert.equal(r.status, "STARTED");
  r = applyTourEvent(r, { type: "step", step: 3 }, NOW);
  assert.equal(r.lastStep, 3);
  r = applyTourEvent(r, { type: "complete", step: 9 }, NOW);
  assert.equal(r.status, "COMPLETED");
  assert.equal(r.lastStep, 9);
  assert.equal(r.completedAt?.toISOString(), NOW.toISOString());
});

test("dismiss records when and where", () => {
  const r = applyTourEvent(applyTourEvent(null, { type: "start" }, NOW), { type: "dismiss", step: 2 }, NOW);
  assert.equal(r.status, "DISMISSED");
  assert.equal(r.lastStep, 2);
  assert.ok(r.dismissedAt);
});

test("terminal states are sticky: a replay never re-opens a finished tour", () => {
  const done: ProgressRow = { status: "COMPLETED", lastStep: 9, completedAt: NOW, dismissedAt: null };
  assert.deepEqual(applyTourEvent(done, { type: "start" }), done);
  assert.deepEqual(applyTourEvent(done, { type: "step", step: 1 }), done);
  // Skipping a replay of a completed tour keeps it COMPLETED.
  assert.equal(applyTourEvent(done, { type: "dismiss", step: 1 }).status, "COMPLETED");

  const skipped: ProgressRow = { status: "DISMISSED", lastStep: 2, completedAt: null, dismissedAt: NOW };
  assert.equal(applyTourEvent(skipped, { type: "start" }).status, "DISMISSED");
  // Finishing a replay of a skipped tour upgrades it.
  assert.equal(applyTourEvent(skipped, { type: "complete" }).status, "COMPLETED");
});

test("step indexes are clamped", () => {
  const r0 = applyTourEvent(null, { type: "start" });
  assert.equal(applyTourEvent(r0, { type: "step", step: -4 }).lastStep, 0);
  assert.equal(applyTourEvent(r0, { type: "step", step: 9999 }).lastStep, MAX_STEP);
  assert.equal(applyTourEvent(r0, { type: "step", step: Number.NaN }).lastStep, 0);
  assert.equal(applyTourEvent(r0, { type: "step", step: 2.7 }).lastStep, 2);
});

/* ── content invariants ─────────────────────────────────────────────────── */

const MC: GameTourContext = {
  family: "minecraft", gameName: "Minecraft", hasGameSettings: true, canApply: true,
  variants: ["Vanilla", "Paper", "Purpur", "Fabric", "Forge"], hasVersion: true, rcon: true,
  logTracked: false, modsInstallable: true, subdomain: true, isFree: false,
};
const GENERIC: GameTourContext = {
  family: "satisfactory", gameName: "Satisfactory", hasGameSettings: true, canApply: false,
  variants: ["Stable", "Experimental"], hasVersion: false, rcon: false,
  logTracked: false, modsInstallable: false, subdomain: true, isFree: false,
};

const ALL_TOURS = [
  buildGameTour(MC),
  buildGameTour(GENERIC),
  buildGameTour({ ...MC, family: "valheim", gameName: "Valheim", rcon: false, logTracked: true, hasVersion: false, variants: ["Vanilla", "BepInEx"] }),
  buildGameTour({ ...GENERIC, family: "terraria", gameName: "Terraria", modsInstallable: true }),
  buildVpsTour({ dedicatedIp: false, osName: "Ubuntu 24.04 LTS", isFree: false }),
  buildHostingTour({ primaryDomain: "example.com" }),
];

test("every tour: unique step ids, one auto-only celebrate step first, concise copy, on-brand", () => {
  for (const t of ALL_TOURS) {
    const ids = t.steps.map((s) => s.id);
    assert.equal(new Set(ids).size, ids.length, `${t.key}: duplicate step id`);
    assert.ok(t.steps[0]!.autoOnly && t.steps[0]!.celebrate, `${t.key}: step 0 must be the one-time ready step`);
    assert.equal(t.steps.filter((s) => s.autoOnly).length, 1, `${t.key}: exactly one auto-only step`);
    assert.ok(t.steps.length <= 18, `${t.key}: too long (${t.steps.length})`);
    for (const s of t.steps) {
      assert.ok(s.body.length <= 260, `${t.key}/${s.id}: body too long (${s.body.length})`);
      assert.ok(s.title.length <= 48, `${t.key}/${s.id}: title too long`);
      assert.ok((s.bullets?.length ?? 0) <= 4, `${t.key}/${s.id}: too many bullets`);
      const text = [s.title, s.body, ...(s.bullets ?? [])].join(" ");
      // Brand rule: never imply a third-party infrastructure provider.
      assert.doesNotMatch(text, /\b(provider|OVH|Hetzner|Proxmox|hypervisor)\b/i, `${t.key}/${s.id}`);
    }
  }
});

test("minecraft tour covers what the brief names", () => {
  const ids = buildGameTour(MC).steps.map((s) => s.id);
  for (const id of ["connect", "power", "game-settings", "mods", "console", "files", "players", "whitelist", "backups", "schedules", "network", "upgrade"]) {
    assert.ok(ids.includes(id), id);
  }
  const settings = buildGameTour(MC).steps.find((s) => s.id === "game-settings")!;
  assert.ok(settings.bullets!.some((b) => /version/i.test(b)) && settings.bullets!.some((b) => /restart/i.test(b)));
});

test("capability honesty: no one-click-install or live-apply promises where they don't exist", () => {
  const t = buildGameTour(GENERIC);
  const mods = t.steps.find((s) => s.id === "mods")!;
  assert.match(mods.body, /aren't available/);
  const gs = t.steps.find((s) => s.id === "game-settings")!;
  assert.match(gs.body, /can't have them pushed/);
  const con = t.steps.find((s) => s.id === "console")!;
  assert.match(con.body, /no remote console/);
  assert.ok(!t.steps.some((s) => s.id === "whitelist"), "whitelist is Minecraft-only");
});

/* Every data-tour id a tour refers to must exist in the source tree — either as a
   literal data-tour="id" or as a templated data-tour={`prefix-${…}`}. */
function walk(dir: string, out: string[] = []): string[] {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (p.endsWith(".tsx")) out.push(p);
  }
  return out;
}

test("every target/navigate id is wired to a real data-tour attribute", () => {
  const src = [...walk("components"), ...walk("app/dashboard")].map((p) => readFileSync(p, "utf8")).join("\n");
  const literals = new Set([...src.matchAll(/data-tour="([^"]+)"/g)].map((m) => m[1]!));
  const prefixes = [...src.matchAll(/data-tour=\{`([a-z-]+)-\$\{/g)].map((m) => m[1]! + "-");
  for (const t of ALL_TOURS) {
    for (const s of t.steps) {
      for (const id of [s.target, ...(s.navigate ?? [])].filter((x): x is string => !!x)) {
        assert.ok(literals.has(id) || prefixes.some((p) => id.startsWith(p)), `${t.key}/${s.id}: no element carries data-tour="${id}"`);
      }
    }
  }
});

/* ── placement ──────────────────────────────────────────────────────────── */

test("spotlight is clipped to the viewport", () => {
  const r = spotRect({ x: -50, y: 100, w: 2000, h: 3000 }, 1280, 800);
  assert.ok(r.x >= 0 && r.y >= 0 && r.x + r.w <= 1280 && r.y + r.h <= 800);
});

test("card goes below a small target near the top, above one near the bottom, centred with none", () => {
  const card = { w: 360, h: 200 };
  assert.equal(placeCard({ spot: { x: 100, y: 80, w: 120, h: 36 }, card, vw: 1280, vh: 800, mobile: false }).side, "bottom");
  assert.equal(placeCard({ spot: { x: 100, y: 700, w: 120, h: 36 }, card, vw: 1280, vh: 800, mobile: false }).side, "top");
  assert.equal(placeCard({ spot: null, card, vw: 1280, vh: 800, mobile: false }).side, "center");
  const p = placeCard({ spot: { x: 1200, y: 80, w: 60, h: 36 }, card, vw: 1280, vh: 800, mobile: false });
  assert.ok(p.x + card.w <= 1280 - 12, "clamped inside the viewport");
});

test("mobile uses a sheet that never covers the target", () => {
  const card = { w: 366, h: 260 };
  assert.equal(placeCard({ spot: { x: 10, y: 100, w: 200, h: 40 }, card, vw: 390, vh: 844, mobile: true }).side, "sheet-bottom");
  assert.equal(placeCard({ spot: { x: 10, y: 700, w: 200, h: 40 }, card, vw: 390, vh: 844, mobile: true }).side, "sheet-top");
});

