// Playwright E2E for first-run tours. Run from the worktree with .env loaded,
// after seed.ts (pass its JSON as SEED env). Not committed.
import { chromium } from "playwright";
import { SignJWT } from "jose";
import { PrismaClient } from "@prisma/client";
import { mkdirSync } from "node:fs";

const BASE = "http://localhost:3115";
const OUT = process.env.OUT ?? "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/tours-shots";
mkdirSync(OUT, { recursive: true });
const seed = JSON.parse(process.env.SEED);
const S = seed.servers;
const db = new PrismaClient();
const secret = new TextEncoder().encode(process.env.AUTH_SECRET);
const COOKIE = process.env.NXEON_COOKIE_NAME;

const results = [];
const ok = (name, cond, detail = "") => { results.push({ name, pass: !!cond, detail }); console.log(`${cond ? "PASS" : "FAIL"}  ${name}${detail ? "  — " + detail : ""}`); };

async function sessionCookie(userId) {
  const t = await new SignJWT({ sub: userId, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(secret);
  return { name: COOKIE, value: t, url: BASE };
}
async function impCookie(adminId, targetId) {
  const t = await new SignJWT({ sub: targetId, adminId, typ: "imp" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1h").sign(secret);
  return { name: `${COOKIE}_imp`, value: t, url: BASE };
}
const row = (key) => db.userTourProgress.findUnique({ where: { userId_serviceKey: { userId: seed.cust, serviceKey: key } } });

const browser = await chromium.launch();
const consoleErrors = [];
async function ctx(opts = {}, user = seed.cust, extraCookies = []) {
  const c = await browser.newContext({ viewport: { width: 1440, height: 900 }, ...opts });
  await c.addCookies([await sessionCookie(user), ...extraCookies]);
  return c;
}
function watch(page, label) {
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(`[${label}] ${m.text().slice(0, 300)}`); });
  page.on("pageerror", (e) => consoleErrors.push(`[${label}] PAGEERROR ${String(e).slice(0, 300)}`));
}
const dialog = (page) => page.locator('#nx-tour-root [role="dialog"]');
async function waitReady(page) {
  await page.waitForFunction(() => document.querySelector('#nx-tour-root [role="dialog"]')?.getAttribute("aria-busy") === "false", null, { timeout: 15000 });
  await page.waitForTimeout(450);
}
async function stepTitle(page) { return (await dialog(page).locator("h2").textContent())?.trim(); }
async function noTourWithin(page, ms) {
  await page.waitForTimeout(ms);
  return (await dialog(page).count()) === 0;
}
async function open(page, id, q = "") {
  await page.goto(`${BASE}/dashboard/servers/${id}${q}`, { waitUntil: "domcontentloaded", timeout: 120000 });
  await page.locator('[data-tour="tour-replay"]').first().waitFor({ timeout: 120000 });
}

try {
  /* 1 — Minecraft first visit: auto-starts, walk every step (desktop, video) */
  {
    const c = await ctx({ recordVideo: { dir: `${OUT}/video`, size: { width: 1440, height: 900 } } });
    const p = await c.newPage(); watch(p, "mc1");
    await open(p, S.mc1);
    await waitReady(p);
    const t0 = await stepTitle(p);
    ok("MC first visit auto-starts with the ready step", /Minecraft server is ready/.test(t0 ?? ""), t0);
    await p.screenshot({ path: `${OUT}/d-mc-00-ready.png` });
    ok("ready step persisted STARTED", (await row("game:minecraft"))?.status === "STARTED");
    const titles = [t0];
    let i = 1;
    for (;;) {
      const btn = dialog(p).getByRole("button", { name: /^(Next|Show me around|Finish)$/ });
      const label = (await btn.textContent())?.trim();
      if (label === "Finish") { await p.screenshot({ path: `${OUT}/d-mc-${String(i).padStart(2, "0")}-last.png` }); await btn.click(); break; }
      await btn.click();
      await waitReady(p);
      const t = await stepTitle(p);
      const spot = await p.locator(".nx-tour-spot").count();
      titles.push(`${t}${spot ? "" : " [no spot]"}`);
      await p.screenshot({ path: `${OUT}/d-mc-${String(i).padStart(2, "0")}.png` });
      i++;
      if (i > 30) break;
    }
    console.log("MC steps:", titles.join(" | "));
    await p.waitForTimeout(600);
    ok("tour closes on Finish", (await dialog(p).count()) === 0);
    const r = await row("game:minecraft");
    ok("MC tour persisted COMPLETED", r?.status === "COMPLETED" && !!r.completedAt, r?.status);
    await p.reload({ waitUntil: "domcontentloaded" });
    await p.locator('[data-tour="tour-replay"]').first().waitFor({ timeout: 60000 });
    ok("MC reload: no tour again", await noTourWithin(p, 3000));
    await c.close();
  }

  /* 2 — second Minecraft server: no tour; replay works and skips the ready step */
  {
    const c = await ctx(); const p = await c.newPage(); watch(p, "mc2");
    await open(p, S.mc2);
    ok("second MC server does not auto-start", await noTourWithin(p, 3500));
    await p.locator('[data-tour="tour-replay"]').click();
    await waitReady(p);
    const t = await stepTitle(p);
    ok("replay opens without the one-time ready step", t === "Your connect address", t);
    await p.screenshot({ path: `${OUT}/d-mc2-replay-connect.png` });
    // Back button absent on first step; Next then Back returns.
    await dialog(p).getByRole("button", { name: "Next" }).click(); await waitReady(p);
    await dialog(p).getByRole("button", { name: "Back" }).click(); await waitReady(p);
    ok("Back returns to previous step", (await stepTitle(p)) === "Your connect address");
    // Missing non-optional target → centred fallback.
    await p.evaluate(() => document.querySelector('[data-tour="game-power"]')?.removeAttribute("data-tour"));
    await dialog(p).getByRole("button", { name: "Next" }).click(); await waitReady(p);
    const fallbackSpot = await p.locator(".nx-tour-spot").count();
    const note = await dialog(p).getByText("isn't showing right now").count();
    ok("missing required target → centred card with note, no spotlight", fallbackSpot === 0 && note === 1, `${await stepTitle(p)}`);
    await p.screenshot({ path: `${OUT}/d-mc2-missing-target.png` });
    // Missing optional target → skipped.
    await p.evaluate(() => document.querySelector('[data-tour="game-vitals"]')?.removeAttribute("data-tour"));
    await dialog(p).getByRole("button", { name: "Next" }).click(); await waitReady(p);
    const afterSkip = await stepTitle(p);
    ok("missing optional target is skipped", afterSkip === "Everything else is a tab away", afterSkip);
    await dialog(p).getByRole("button", { name: "Skip tour" }).click();
    await p.waitForTimeout(500);
    ok("skip closes the replay", (await dialog(p).count()) === 0);
    ok("replay skip keeps COMPLETED", (await row("game:minecraft"))?.status === "COMPLETED");
    await c.close();
  }

  /* 3 — Valheim: first visit of a different family auto-starts; Esc dismisses */
  {
    const c = await ctx(); const p = await c.newPage(); watch(p, "valheim");
    await open(p, S.vh);
    await waitReady(p);
    ok("first Valheim server auto-starts its own tour", /Valheim server is ready/.test((await stepTitle(p)) ?? ""));
    await dialog(p).getByRole("button", { name: "Show me around" }).click(); await waitReady(p);
    await p.screenshot({ path: `${OUT}/d-valheim-connect.png` });
    // jump to settings step by pressing ArrowRight a few times
    for (let k = 0; k < 4; k++) { await p.keyboard.press("ArrowRight"); await waitReady(p); }
    await p.screenshot({ path: `${OUT}/d-valheim-${(await stepTitle(p))?.replace(/\W+/g, "-")}.png` });
    await p.keyboard.press("Escape");
    await p.waitForTimeout(500);
    const r = await row("game:valheim");
    ok("Esc dismisses and persists DISMISSED", (await dialog(p).count()) === 0 && r?.status === "DISMISSED", `${r?.status} lastStep=${r?.lastStep}`);
    await p.reload({ waitUntil: "domcontentloaded" });
    await p.locator('[data-tour="tour-replay"]').first().waitFor({ timeout: 60000 });
    ok("Valheim reload after dismiss: no tour", await noTourWithin(p, 3000));
    await c.close();
  }

  /* 4 — admin impersonation: no auto-start, no persistence, no opt-out link */
  {
    const c = await ctx({}, seed.admin, [await impCookie(seed.admin, seed.cust)]);
    const p = await c.newPage(); watch(p, "imp");
