60	type Resolved = { index: number; el: HTMLElement | null };
61	
62	export default function TourOverlay({
63	  title, steps, startAt, onStep, onFinish, onDismiss, onOptOut, canOptOut,
64	}: TourOverlayProps) {
65	  const reduced = useMedia(REDUCED_Q);
66	  const mobile = useMedia(MOBILE_Q);
67	  const [root, setRoot] = useState<HTMLElement | null>(null);
68	  const [index, setIndex] = useState(() => Math.min(Math.max(0, startAt), steps.length - 1));
69	  const [resolved, setResolved] = useState<Resolved | null>(null);
70	  const [box, setBox] = useState<Box | null>(null);
71	  const [vp, setVp] = useState({ w: 1280, h: 800 });
72	  const [cardSize, setCardSize] = useState({ w: 360, h: 220 });
73	  const dir = useRef<1 | -1>(1);
74	  const cardRef = useRef<HTMLDivElement>(null);
75	  const primaryRef = useRef<HTMLButtonElement>(null);
76	  const returnFocus = useRef<Element | null>(null);
77	  const committed = useRef<number | null>(null);
78	
79	  /* ── portal root + page inert ───────────────────────────────────────── */
80	  useEffect(() => {
81	    returnFocus.current = document.activeElement;
82	    const el = document.createElement("div");
83	    el.id = "nx-tour-root";
84	    document.body.appendChild(el);
85	    setRoot(el);
86	    setPageInert(el, true);
87	    return () => {
88	      setPageInert(el, false);
89	      el.remove();
90	      const back = returnFocus.current as HTMLElement | null;
91	      if (back && typeof back.focus === "function" && back.isConnected) back.focus({ preventScroll: true });
92	    };
93	  }, []);
