/**
 * Server Component mount for a domain's dashboard (app/dashboard/domains/[id]).
 * serviceKey "domain"; ready once the registration is ACTIVE.
 */

import { TourLauncher } from "./TourLauncher";
import { tourStateFor } from "@/lib/tours/server";
import { buildDomainTour } from "@/lib/tours/domain";

export async function DomainTour({
  domain, className,
}: {
  domain: { name: string; userId: string; status: string; createdAt: Date };
  className?: string;
}) {
  const state = await tourStateFor({
    serviceKey: "domain",
    ownerId: domain.userId,
    ready: domain.status === "ACTIVE",
    createdAt: domain.createdAt,
  });
  return (
    <TourLauncher
      tour={buildDomainTour({ domainName: domain.name })}
      autoStart={state.autoStart}
      resumeAt={state.resumeAt}
      fresh={state.fresh}
      persist={state.persist}
      className={className}
    />
  );
}
EOF
